def compile_papyrus_scripts() -> None:
    os.makedirs(PAPYRUS_OUT_DIR, exist_ok=True)
    base_scripts = os.path.join(FO4_DATA_DIR, "Scripts", "Source", "Base")
    cmd = [
        PAPYRUS_COMPILER,
        PAPYRUS_SRC_DIR,
        "-f=Institute_Papyrus_Flags.flg",
        f"-i={base_scripts};{PAPYRUS_SRC_DIR}",
        f"-o={PAPYRUS_OUT_DIR}",
        "-a",
    ]
    subprocess.run(cmd, check=True)
    n_pex = len([fn for fn in os.listdir(PAPYRUS_OUT_DIR) if fn.lower().endswith(".pex")])
    print(f"[Papyrus ES] {n_pex} scripts compilados en papyrus_out/.")


def _synthesize_single_clip(
    api_key: str,
    vtyp_edid: str,
    voice_id: str,
    low_fid: int,
    resp_idx: int,
    tts_text: str,
    ba2_voice_map: dict[str, str],
) -> None:
    vtyp_cache_dir = os.path.join(VOICES_DIR, vtyp_edid)
    os.makedirs(vtyp_cache_dir, exist_ok=True)

    fname_base = f"{low_fid:08X}_{resp_idx}"
    mp3_path = os.path.join(vtyp_cache_dir, f"{fname_base}.mp3")
    wav_path = os.path.join(vtyp_cache_dir, f"{fname_base}.wav")
    xwm_path = os.path.join(vtyp_cache_dir, f"{fname_base}.xwm")
    txt_cache = os.path.join(vtyp_cache_dir, f"{fname_base}.txt")

    sfx_mix_FNAME_SET = {
        "00005033_1",
        "00005031_1",
        "00005030_1",
        "00005035_1",
        "00005015_1",
        "00005032_1",
    }
    cache_sig = f"{tts_text}|sfx_mix_v2" if fname_base in sfx_mix_FNAME_SET else tts_text

    cached_txt = None
    if os.path.exists(txt_cache):
        with open(txt_cache, "r", encoding="utf-8") as tf:
            cached_txt = tf.read()

    if not os.path.exists(xwm_path) or cached_txt != cache_sig or "--regen-voices" in sys.argv:
        need_tts = (
            not os.path.exists(mp3_path)
            or cached_txt is None
            or not cached_txt.startswith(tts_text)
            or "--regen-voices" in sys.argv
        )
        if need_tts:
            print(f"  [ElevenLabs ES] ({vtyp_edid}) {fname_base}: {tts_text[:72]}...")
            url = f"https://api.elevenlabs.io/v1/text-to-speech/{voice_id}?output_format=mp3_44100_128"
            payload = {
                "text": tts_text,
                "model_id": "eleven_multilingual_v2",
                "voice_settings": {
                    "stability": 0.60,
                    "similarity_boost": 0.82,
                    "style": 0.16,
                    "use_speaker_boost": True,
                },
            }
            req = urllib.request.Request(
                url,
                data=json.dumps(payload).encode("utf-8"),
                headers={
                    "xi-api-key": api_key,
                    "Content-Type": "application/json",
                    "Accept": "audio/mpeg",
                },
                method="POST",
            )
            with urllib.request.urlopen(req, timeout=60) as resp:
                with open(mp3_path, "wb") as wf:
                    wf.write(resp.read())

        s_turb = os.path.join(SFX_DIR, "sfx_water_turbine_startup.mp3")
        s_cheer = os.path.join(SFX_DIR, "sfx_vault_residents_cheer.mp3")
        s_pump = os.path.join(SFX_DIR, "sfx_necropolis_pump_repair.mp3")

        if fname_base in ("00005033_1", "00005031_1", "00005030_1", "00005035_1") and os.path.exists(s_turb) and os.path.exists(s_cheer):
            print(f"  [ElevenLabs SFX Mix] Mixing turbine water + cheering crowd into {fname_base}...")
            if fname_base == "00005033_1":
                fc = (
                    "[0:a]highpass=f=85,lowpass=f=7800,acompressor=threshold=-16dB:ratio=2.5:makeup=4dB,volume=1.55,adelay=1500|1500[v];"
                    "[1:a]volume=1.40[t];"
                    "[2:a]adelay=1100|1100,volume=1.30[c];"
                    "[v][t][c]amix=inputs=3:duration=longest:dropout_transition=0:normalize=0,alimiter=limit=0.96"
                )
            elif fname_base in ("00005031_1", "00005030_1"):
                fc = (
                    "[0:a]highpass=f=85,lowpass=f=7800,acompressor=threshold=-16dB:ratio=2.5:makeup=4dB,volume=1.55,adelay=550|550[v];"
                    "[1:a]volume=0.90[t];"
                    "[2:a]volume=1.35[c];"
                    "[v][t][c]amix=inputs=3:duration=longest:dropout_transition=0:normalize=0,alimiter=limit=0.96"
                )
            else:
                fc = (
                    "[0:a]highpass=f=85,lowpass=f=7800,acompressor=threshold=-16dB:ratio=2.5:makeup=4dB,volume=1.55,adelay=400|400[v];"
                    "[1:a]volume=1.05[t];"
                    "[2:a]volume=1.15[c];"
                    "[v][t][c]amix=inputs=3:duration=longest:dropout_transition=0:normalize=0,alimiter=limit=0.96"
                )
            subprocess.run(
                [
                    FFMPEG_BIN,
                    "-y",
                    "-loglevel",
                    "error",
                    "-i",
                    mp3_path,
                    "-i",
                    s_turb,
                    "-i",
                    s_cheer,
                    "-filter_complex",
                    fc,
                    "-bitexact",
                    "-map_metadata",
                    "-1",
                    "-ar",
                    "44100",
                    "-ac",
                    "1",
                    "-sample_fmt",
                    "s16",
                    wav_path,
                ],
                check=True,
            )
        elif fname_base == "00005015_1" and os.path.exists(s_turb):
            print(f"  [ElevenLabs SFX Mix] Mixing water turbine flow into {fname_base}...")
            fc = (
                "[0:a]highpass=f=85,lowpass=f=7800,acompressor=threshold=-16dB:ratio=2.5:makeup=4dB,volume=1.55[v];"
                "[1:a]volume=0.95[t];"
                "[v][t]amix=inputs=2:duration=first:dropout_transition=0:normalize=0,alimiter=limit=0.96"
            )
            subprocess.run(
                [
                    FFMPEG_BIN,
                    "-y",
                    "-loglevel",
                    "error",
                    "-i",
                    mp3_path,
                    "-i",
                    s_turb,
                    "-filter_complex",
                    fc,
                    "-bitexact",
                    "-map_metadata",
                    "-1",
                    "-ar",
                    "44100",
                    "-ac",
                    "1",
                    "-sample_fmt",
                    "s16",
                    wav_path,
                ],
                check=True,
            )
        elif fname_base == "00005032_1" and os.path.exists(s_pump):
            print(f"  [ElevenLabs SFX Mix] Mixing Necropolis pump startup into {fname_base}...")
            fc = (
                "[0:a]highpass=f=85,lowpass=f=7800,acompressor=threshold=-16dB:ratio=2.5:makeup=4dB,volume=1.55,adelay=1100|1100[v];"
                "[1:a]volume=1.35[p];"
                "[v][p]amix=inputs=2:duration=longest:dropout_transition=0:normalize=0,alimiter=limit=0.96"
            )
            subprocess.run(
                [
                    FFMPEG_BIN,
                    "-y",
                    "-loglevel",
                    "error",
                    "-i",
                    mp3_path,
                    "-i",
                    s_pump,
                    "-filter_complex",
                    fc,
                    "-bitexact",
                    "-map_metadata",
                    "-1",
                    "-ar",
                    "44100",
                    "-ac",
                    "1",
                    "-sample_fmt",
                    "s16",
                    wav_path,
                ],
                check=True,
            )
        else:
            if vtyp_edid == "CrSuperMutant":
                af_filter = (
                    "asetrate=44100*0.80,aresample=44100,atempo=1.18,"
                    "highpass=f=60,lowpass=f=6500,"
                    "acompressor=threshold=-16dB:ratio=3.0:makeup=4dB,volume=1.35"
                )
            else:
                af_filter = (
                    "highpass=f=85,lowpass=f=7800,"
                    "acompressor=threshold=-16dB:ratio=2.5:makeup=3dB,volume=1.25"
                )
            subprocess.run(
                [
                    FFMPEG_BIN,
                    "-y",
                    "-loglevel",
                    "error",
                    "-i",
                    mp3_path,
                    "-af",
                    af_filter,
                    "-bitexact",
                    "-map_metadata",
                    "-1",
                    "-ar",
                    "44100",
                    "-ac",
                    "1",
                    "-sample_fmt",
                    "s16",
                    wav_path,
                ],
                check=True,
            )
        subprocess.run(
            [XWMAENCODE_BIN, "-b", "48000", wav_path, xwm_path],
            check=True,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
        )
        with open(txt_cache, "w", encoding="utf-8") as tf:
            tf.write(cache_sig)

    rel_key = f"sound\\voice\\{ESP_NAME.lower()}\\{vtyp_edid.lower()}\\{fname_base.lower()}.xwm"
    ba2_voice_map[rel_key] = xwm_path


