def synthesize_all_sfx(api_key: str) -> dict[str, str]:
    os.makedirs(SFX_DIR, exist_ok=True)
    ba2_sfx_map: dict[str, str] = {}

    for sfx in V13_SFX_DEFS:
        fname = sfx["name"]
        prompt = sfx["prompt"]
        dur = sfx["duration"]
        mp3_path = os.path.join(SFX_DIR, f"{fname}.mp3")
        wav_path = os.path.join(SFX_DIR, f"{fname}.wav")
        xwm_path = os.path.join(SFX_DIR, f"{fname}.xwm")
        txt_cache = os.path.join(SFX_DIR, f"{fname}.txt")
        sfx_sig = f"{prompt}|v2_bitexact"

        cached_prompt = None
        if os.path.exists(txt_cache):
            with open(txt_cache, "r", encoding="utf-8") as tf:
                cached_prompt = tf.read()

        if (
            not os.path.exists(wav_path)
            or not os.path.exists(xwm_path)
            or cached_prompt != sfx_sig
            or "--regen-sfx" in sys.argv
        ):
            need_gen = (
                not os.path.exists(mp3_path)
                or cached_prompt is None
                or not cached_prompt.startswith(prompt)
                or "--regen-sfx" in sys.argv
            )
            if need_gen:
                print(f"  [ElevenLabs SFX] {fname} ({dur}s): {prompt[:68]}...")
                url = "https://api.elevenlabs.io/v1/sound-generation"
                payload = {
                    "text": prompt,
                    "duration_seconds": dur,
                    "prompt_influence": 0.45,
                }
                req = urllib.request.Request(
                    url,
                    data=json.dumps(payload).encode("utf-8"),
                    headers={
                        "xi-api-key": api_key,
                        "Content-Type": "application/json",
                        "Accept": "audio/mpeg",
                    },
                    method="POST",
                )
                with urllib.request.urlopen(req, timeout=60) as resp:
                    with open(mp3_path, "wb") as wf:
                        wf.write(resp.read())
            else:
                print(f"  [ElevenLabs SFX Remaster] {fname}...")

            subprocess.run(
                [
                    FFMPEG_BIN,
                    "-y",
                    "-loglevel",
                    "error",
                    "-i",
                    mp3_path,
                    "-af",
                    "highpass=f=45,lowpass=f=14000,acompressor=threshold=-16dB:ratio=3.0:makeup=5dB,volume=1.65",
                    "-bitexact",
                    "-map_metadata",
                    "-1",
                    "-ar",
                    "44100",
                    "-ac",
                    "1",
                    "-sample_fmt",
                    "s16",
                    wav_path,
                ],
                check=True,
            )
            subprocess.run(
                [XWMAENCODE_BIN, "-b", "48000", wav_path, xwm_path],
                check=True,
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
            )
            with open(txt_cache, "w", encoding="utf-8") as tf:
                tf.write(sfx_sig)

        ba2_sfx_map[f"sound\\fx\\v13chronicles\\{fname.lower()}.xwm"] = xwm_path

    return ba2_sfx_map


