    0x000DF66B,  # MUSRadioDiamondTheInkSpotsMaybe (Fallout 1 Theme!)
    0x000DF669,  # MUSRadioDiamondTheInkSpotsIDontWantToSet
    0x0012DA54,  # MUSRadioDiamondTheFiveStarsAtomBombBaby
    0x00141994,  # MUSRadioDiamondEltonBrittUraniumFever
