    0x0012DA4F,  # MUSRadioDiamondNatKingColeOrangeColoredSky
    0x000DF674,  # MUSRadioDiamondBingCrosbyPistolPackinMama
    0x00141165,  # MUSRadioDiamondConnieAllenRocket69
    0x0012DA55,  # MUSRadioDiamondWarrenSmithUraniumRock
