def synthesize_all_radio_tracks(
    api_key: str,
) -> tuple[dict[str, str], list[tuple[int, str, str]], list[int]]:
    os.makedirs(RADIO_DJ_DIR, exist_ok=True)
    os.makedirs(RADIO_MUSIC_SRC_DIR, exist_ok=True)
    os.makedirs(RADIO_MUSIC_CACHE_DIR, exist_ok=True)

    ba2_radio_map: dict[str, str] = {}
    custom_sndr_defs: list[tuple[int, str, str]] = []
    dj_sndr_fids: list[int] = []

    # 1. Synthesize the 24 ElevenLabs Fallout 1 (2161) Radio DJ broadcasts
    dj_filter_ver = "v2_loud"
    for dj in V13_RADIO_DJ_DEFS:
        fname = dj["name"]
        sndr_fid = dj["sndr_fid"]
        edid = dj["edid"]
        tts_text = dj["tts"]
        cache_key = f"{tts_text}|{dj_filter_ver}"
        mp3_path = os.path.join(RADIO_DJ_DIR, f"{fname}.mp3")
        wav_path = os.path.join(RADIO_DJ_DIR, f"{fname}.wav")
        xwm_path = os.path.join(RADIO_DJ_DIR, f"{fname}.xwm")
        txt_cache = os.path.join(RADIO_DJ_DIR, f"{fname}.txt")

        cached_txt = None
        if os.path.exists(txt_cache):
            with open(txt_cache, "r", encoding="utf-8") as tf:
                cached_txt = tf.read()

        if (
            not os.path.exists(xwm_path)
            or cached_txt != cache_key
            or "--regen-radio-dj" in sys.argv
        ):
            need_tts = (
                not os.path.exists(mp3_path)
                or cached_txt is None
                or not cached_txt.startswith(tts_text)
                or "--regen-radio-dj" in sys.argv
            )
            if need_tts:
                print(f"  [ElevenLabs Radio El Eje 2161] {fname}: {tts_text[:72]}...")
                url = f"https://api.elevenlabs.io/v1/text-to-speech/{RADIO_DJ_VOICE_ID}"
                payload = {
                    "text": tts_text,
                    "model_id": "eleven_multilingual_v2",
                    "voice_settings": {
                        "stability": 0.58,
                        "similarity_boost": 0.82,
                        "style": 0.28,
                        "use_speaker_boost": True,
                    },
                }
                req = urllib.request.Request(
                    url,
                    data=json.dumps(payload).encode("utf-8"),
                    headers={
                        "xi-api-key": api_key,
                        "Content-Type": "application/json",
                        "Accept": "audio/mpeg",
                    },
                    method="POST",
                )
                with urllib.request.urlopen(req, timeout=90) as resp:
                    with open(mp3_path, "wb") as wf:
                        wf.write(resp.read())
            else:
                print(f"  [Radio DJ Remaster Loudness] {fname}...")

            # High-clarity broadcast compression + loudness boost so the DJ cuts cleanly over wasteland audio
            af_radio_dj = (
                "highpass=f=140,lowpass=f=5600,"
                "acompressor=threshold=-20dB:ratio=4.0:makeup=7dB,"
                "alimiter=limit=0.96,volume=1.55"
            )
            subprocess.run(
                [
                    FFMPEG_BIN,
                    "-y",
                    "-loglevel",
                    "error",
                    "-i",
                    mp3_path,
                    "-af",
                    af_radio_dj,
                    "-ar",
                    "44100",
                    "-ac",
                    "1",
                    "-sample_fmt",
                    "s16",
                    wav_path,
                ],
                check=True,
            )
            subprocess.run(
                [XWMAENCODE_BIN, "-b", "48000", wav_path, xwm_path],
                check=True,
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
            )
            with open(txt_cache, "w", encoding="utf-8") as tf:
                tf.write(cache_key)

        ba2_radio_map[f"sound\\fx\\mus\\radio\\vault13\\{fname}.xwm"] = xwm_path
        custom_sndr_defs.append(
            (sndr_fid, edid, f"Data\\Sound\\FX\\MUS\\Radio\\Vault13\\{fname}.wav")
        )
        dj_sndr_fids.append(sndr_fid)

        # If this DJ entry also defines an English broadcast ("tts_en"), synthesize and cache it in assets/radio_dj_en/
        tts_en_text = dj.get("tts_en")
        if tts_en_text:
            radio_dj_en_dir = os.path.join(THIS_DIR, "assets", "radio_dj_en")
            os.makedirs(radio_dj_en_dir, exist_ok=True)
            en_cache_key = f"{tts_en_text}|{dj_filter_ver}"
            en_mp3_path = os.path.join(radio_dj_en_dir, f"{fname}.mp3")
            en_wav_path = os.path.join(radio_dj_en_dir, f"{fname}.wav")
            en_xwm_path = os.path.join(radio_dj_en_dir, f"{fname}.xwm")
            en_txt_cache = os.path.join(radio_dj_en_dir, f"{fname}.txt")
            en_cached_txt = None
            if os.path.exists(en_txt_cache):
                with open(en_txt_cache, "r", encoding="utf-8") as etf:
                    en_cached_txt = etf.read()
            if (
                not os.path.exists(en_xwm_path)
                or en_cached_txt != en_cache_key
                or "--regen-radio-dj" in sys.argv
            ):
                print(f"  [ElevenLabs Radio Hub 2161 EN] {fname}: {tts_en_text[:72]}...")
                url_en = f"https://api.elevenlabs.io/v1/text-to-speech/{RADIO_DJ_VOICE_ID}"
                payload_en = {
                    "text": tts_en_text,
                    "model_id": "eleven_multilingual_v2",
                    "voice_settings": {
                        "stability": 0.58,
                        "similarity_boost": 0.82,
                        "style": 0.28,
                        "use_speaker_boost": True,
                    },
                }
                req_en = urllib.request.Request(
                    url_en,
                    data=json.dumps(payload_en).encode("utf-8"),
                    headers={
                        "xi-api-key": api_key,
                        "Content-Type": "application/json",
                        "Accept": "audio/mpeg",
                    },
                    method="POST",
                )
                with urllib.request.urlopen(req_en, timeout=90) as resp_en:
                    with open(en_mp3_path, "wb") as wf_en:
                        wf_en.write(resp_en.read())
                af_radio_dj_en = (
                    "highpass=f=140,lowpass=f=5600,"
                    "acompressor=threshold=-20dB:ratio=4.0:makeup=7dB,"
                    "alimiter=limit=0.96,volume=1.55"
                )
                subprocess.run(
                    [
                        FFMPEG_BIN,
                        "-y",
                        "-loglevel",
                        "error",
                        "-i",
                        en_mp3_path,
                        "-af",
                        af_radio_dj_en,
                        "-ar",
                        "44100",
                        "-ac",
                        "1",
                        "-sample_fmt",
                        "s16",
                        en_wav_path,
                    ],
                    check=True,
                )
                subprocess.run(
                    [XWMAENCODE_BIN, "-b", "48000", en_wav_path, en_xwm_path],
                    check=True,
                    stdout=subprocess.DEVNULL,
                    stderr=subprocess.DEVNULL,
                )
                with open(en_txt_cache, "w", encoding="utf-8") as etf:
                    etf.write(en_cache_key)

    # 2. Scan radio_music/ for user's custom Suno Fallout tracks (.mp3, .wav, .flac, .ogg, .m4a)
    # Sort so that "Ballad of Na Fianna" is placed at slot 24 (preserving cached slots 01..23)
    audio_exts = (".mp3", ".wav", ".flac", ".ogg", ".m4a")
    user_song_files = sorted(
        (
            fn
            for fn in os.listdir(RADIO_MUSIC_SRC_DIR)
            if os.path.isfile(os.path.join(RADIO_MUSIC_SRC_DIR, fn))
            and fn.lower().endswith(audio_exts)
        ),
        key=lambda fn: (1 if "ballad of na fianna" in fn.lower() else 0, fn.lower()),
    )

    song_sndr_fids: list[int] = []
    bardo_song_fid: int | None = None
    for idx_s, src_fn in enumerate(user_song_files, 1):
        if idx_s > 60:
            break
        src_path = os.path.join(RADIO_MUSIC_SRC_DIR, src_fn)
        st_info = os.stat(src_path)
        sig_str = f"{src_fn}|{st_info.st_size}|{int(st_info.st_mtime)}|v2_loud"
        track_stem = f"v13_radio_song_{idx_s:02d}"
        wav_path = os.path.join(RADIO_MUSIC_CACHE_DIR, f"{track_stem}.wav")
        xwm_path = os.path.join(RADIO_MUSIC_CACHE_DIR, f"{track_stem}.xwm")
        sig_path = os.path.join(RADIO_MUSIC_CACHE_DIR, f"{track_stem}.sig")

        cached_sig = None
        if os.path.exists(sig_path):
            with open(sig_path, "r", encoding="utf-8") as sf:
                cached_sig = sf.read()

        if not os.path.exists(xwm_path) or cached_sig != sig_str:
            print(f"  [Radio Music Suno -> XWM] ({idx_s}/{len(user_song_files)}) {src_fn}...")
            af_song = (
                "highpass=f=55,lowpass=f=12500,"
                "acompressor=threshold=-16dB:ratio=2.5:makeup=4dB,"
                "alimiter=limit=0.95,volume=1.35"
            )
            subprocess.run(
                [
                    FFMPEG_BIN,
                    "-y",
                    "-loglevel",
                    "error",
                    "-i",
                    src_path,
                    "-af",
                    af_song,
                    "-ar",
                    "44100",
                    "-ac",
                    "1",
                    "-sample_fmt",
                    "s16",
                    wav_path,
                ],
                check=True,
            )
            subprocess.run(
                [XWMAENCODE_BIN, "-b", "96000", wav_path, xwm_path],
                check=True,
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
            )
            if os.path.exists(wav_path):
                try:
                    os.remove(wav_path)
                except OSError:
                    pass
            with open(sig_path, "w", encoding="utf-8") as sf:
                sf.write(sig_str)
        else:
            print(f"  [Radio Music Suno Cached] ({idx_s}/{len(user_song_files)}) {src_fn}")

        sndr_fid = 0x01008620 + (idx_s - 1)
        edid = f"SNDRV13RadioSong{idx_s:02d}"
        ba2_radio_map[f"sound\\fx\\mus\\radio\\vault13\\{track_stem}.xwm"] = xwm_path
        custom_sndr_defs.append(
            (sndr_fid, edid, f"Data\\Sound\\FX\\MUS\\Radio\\Vault13\\{track_stem}.wav")
        )
        song_sndr_fids.append(sndr_fid)
        if "ballad of na fianna" in src_fn.lower():
            bardo_song_fid = sndr_fid

    if not song_sndr_fids:
        print(
            "  [Radio El Eje 2161] (Aún no hay canciones en radio_music/; usando 12 clásicos de Fallout como sintonía provisional hasta añadir las canciones de Suno)"
        )
        song_sndr_fids = list(FALLBACK_FALLOUT_RADIO_SNDRS)

    # Interleave DJ broadcasts and songs so every DJ story and every song is heard in rotation,
    # and guarantee that DJ 25 (0x01008619, Patrick the Celt's story) ALWAYS plays immediately before
    # "Ballad of Na Fianna" (both right after the opening track and in its regular cycle slot).
    bardo_dj_fid = 0x01008619
    playlist_fids: list[int] = []
    regular_djs = [f for f in dj_sndr_fids if f != bardo_dj_fid]
    regular_songs = [f for f in song_sndr_fids if f != bardo_song_fid]
    total_pairs = max(len(regular_djs), len(regular_songs))
    for i in range(total_pairs):
        playlist_fids.append(regular_djs[i % len(regular_djs)])
        playlist_fids.append(regular_songs[i % len(regular_songs)])
        if i == 0 and bardo_song_fid is not None and bardo_dj_fid in dj_sndr_fids:
            playlist_fids.append(bardo_dj_fid)
            playlist_fids.append(bardo_song_fid)
    if bardo_song_fid is not None and bardo_dj_fid in dj_sndr_fids:
        playlist_fids.append(bardo_dj_fid)
        playlist_fids.append(bardo_song_fid)

    return ba2_radio_map, custom_sndr_defs, playlist_fids


def synthesize_all_voices(api_key: str) -> dict[str, str]:
    os.makedirs(VOICES_DIR, exist_ok=True)
    ba2_voice_map: dict[str, str] = {}

    jac_cache_dir = os.path.join(VOICES_DIR, VTYP_EDID)
    if os.path.isdir(jac_cache_dir):
        for src_base, dst_base in (
            ("00004013_1", "00004015_1"),
        ):
            for ext in (".mp3", ".wav", ".xwm", ".txt"):
                s_p = os.path.join(jac_cache_dir, src_base + ext)
                d_p = os.path.join(jac_cache_dir, dst_base + ext)
                if os.path.exists(s_p) and not os.path.exists(d_p):
                    shutil.copy2(s_p, d_p)

    # Mirror cached Harry confrontation wheel clips (000053A0..000053AE -> 000053B0..000053BE and 000053C0..000053CE + 0000503A..0000503E)
    for v_folder, id_range in (
        (PLAYER_MALE_VTYP, range(0x000053A0, 0x000053A4)),
        (PLAYER_FEMALE_VTYP, range(0x000053A4, 0x000053A8)),
        ("CrSuperMutant", range(0x000053A8, 0x000053AF)),
    ):
        vf_dir = os.path.join(VOICES_DIR, v_folder)
        if os.path.isdir(vf_dir):
            for src_id in id_range:
                for offset_val in (0x10, 0x20):
                    dst_id = src_id + offset_val
                    for ext in (".mp3", ".wav", ".xwm", ".txt"):
                        s_p = os.path.join(vf_dir, f"{src_id:08X}_1{ext}")
                        d_p = os.path.join(vf_dir, f"{dst_id:08X}_1{ext}")
                        if os.path.exists(s_p) and not os.path.exists(d_p):
                            shutil.copy2(s_p, d_p)
    sm_vf_dir = os.path.join(VOICES_DIR, "CrSuperMutant")
    if os.path.isdir(sm_vf_dir):
        for src_id, dst_id in (
            (0x000053A8, 0x0000503A),
            (0x000053A9, 0x0000503B),
            (0x000053AA, 0x0000503C),
            (0x000053AB, 0x0000503D),
            (0x000053AE, 0x0000503E),
        ):
            for ext in (".mp3", ".wav", ".xwm", ".txt"):
                s_p = os.path.join(sm_vf_dir, f"{src_id:08X}_1{ext}")
                d_p = os.path.join(sm_vf_dir, f"{dst_id:08X}_1{ext}")
                if os.path.exists(s_p) and not os.path.exists(d_p):
                    shutil.copy2(s_p, d_p)

    # Copy any cached CrSuperMutant audio clips into V13HarrySuperMutantVoice cache dir so no regeneration is needed
    src_sm_vdir = os.path.join(VOICES_DIR, "CrSuperMutant")
    dst_harry_vdir = os.path.join(VOICES_DIR, HARRY_SUPERMUTANT_VTYP)
    if os.path.isdir(src_sm_vdir):
        os.makedirs(dst_harry_vdir, exist_ok=True)
        for fn in os.listdir(src_sm_vdir):
            s_p = os.path.join(src_sm_vdir, fn)
            d_p = os.path.join(dst_harry_vdir, fn)
            if os.path.isfile(s_p) and not os.path.exists(d_p):
                shutil.copy2(s_p, d_p)

    for gdef in (
        GREETING_INFOS
        + ACT2_GREETING_INFOS
        + ACT3_GREETING_INFOS
        + ACT4_GREETING_INFOS
        + ACT5_GREETING_INFOS
        + SHADY_SANDS_GREETING_INFOS
        + JUNKTOWN_GREETING_INFOS
        + HUB_GREETING_INFOS
        + KHANS_GREETING_INFOS
        + TANDI_RESCUE_GREETING_INFOS
        + JUNKTOWN_SYNDICATE_GREETING_INFOS
        + HUB_SYNDICATE_GREETING_INFOS
        + GLOW_GREETING_INFOS
        + BONEYARD_GREETING_INFOS
        + PATRICK_CELT_GREETING_INFOS
    ):
        low_fid = gdef["info_fid"] & 0x00FFFFFF
        g_vtyp = gdef.get("speaker_vtyp", VTYP_EDID)
        g_vid = gdef.get("speaker_voice_id", JACOREN_VOICE_ID)
        for r_idx, (_sub, tts_txt) in enumerate(gdef["responses"], 1):
            _synthesize_single_clip(
                api_key,
                g_vtyp,
                g_vid,
                low_fid,
                r_idx,
                tts_txt,
                ba2_voice_map=ba2_voice_map,
            )

    for sdef in (
        SCENE_DEFINITIONS
        + ACT2_SCENE_DEFINITIONS
        + ACT3_SCENE_DEFINITIONS
        + ACT4_SCENE_DEFINITIONS
        + ACT5_SCENE_DEFINITIONS
        + SHADY_SANDS_SCENE_DEFINITIONS
        + JUNKTOWN_SCENE_DEFINITIONS
        + HUB_SCENE_DEFINITIONS
        + KHANS_SCENE_DEFINITIONS
        + TANDI_RESCUE_SCENE_DEFINITIONS
        + JUNKTOWN_SYNDICATE_SCENE_DEFINITIONS
        + HUB_SYNDICATE_SCENE_DEFINITIONS
        + GLOW_SCENE_DEFINITIONS
        + BONEYARD_SCENE_DEFINITIONS
        + PATRICK_CELT_SCENE_DEFINITIONS
    ):
        s_vtyp = sdef.get("speaker_vtyp", VTYP_EDID)
        s_vid = sdef.get("speaker_voice_id", JACOREN_VOICE_ID)
        if "intro_npc_action" in sdef:
            in_act = sdef["intro_npc_action"]
            in_low = in_act["info_fid"] & 0x00FFFFFF
            _synthesize_single_clip(
                api_key,
                s_vtyp,
                s_vid,
                in_low,
                1,
                in_act["tts"],
                ba2_voice_map=ba2_voice_map,
            )
        for act in sdef["actions"]:
            for opt in act["options"]:
                p_low = opt["p_info"] & 0x00FFFFFF
                _synthesize_single_clip(
                    api_key,
                    PLAYER_MALE_VTYP,
                    PLAYER_MALE_VOICE_ID,
                    p_low,
                    1,
                    opt["p_tts"],
                    ba2_voice_map=ba2_voice_map,
                )
                if "p_info_f" in opt:
                    pf_low = opt["p_info_f"] & 0x00FFFFFF
                    _synthesize_single_clip(
                        api_key,
                        PLAYER_FEMALE_VTYP,
                        PLAYER_FEMALE_VOICE_ID,
                        pf_low,
                        1,
                        opt["p_tts_f"],
                        ba2_voice_map=ba2_voice_map,
                    )
                else:
                    _synthesize_single_clip(
                        api_key,
                        PLAYER_FEMALE_VTYP,
                        PLAYER_FEMALE_VOICE_ID,
                        p_low,
                        1,
                        opt["p_tts"],
                        ba2_voice_map=ba2_voice_map,
                    )
                n_low = opt["n_info"] & 0x00FFFFFF
                for r_idx, (_sub, tts_txt) in enumerate(opt["n_responses"], 1):
                    _synthesize_single_clip(
                        api_key,
                        s_vtyp,
                        s_vid,
                        n_low,
                        r_idx,
                        tts_txt,
                        ba2_voice_map=ba2_voice_map,
                    )
                if "n_fail_info" in opt:
                    nf_low = opt["n_fail_info"] & 0x00FFFFFF
                    for r_idx, (_sub, tts_txt) in enumerate(opt["n_fail_responses"], 1):
                        _synthesize_single_clip(
                            api_key,
                            s_vtyp,
                            s_vid,
                            nf_low,
                            r_idx,
                            tts_txt,
                            ba2_voice_map=ba2_voice_map,
                        )

    for rdef in V13_RESIDENT_DEFS:
        v_edid = rdef["vtyp_edid"]
        v_cache_dir = os.path.join(VOICES_DIR, v_edid)
        for g_fid_key, tts_key in (
            ("gree_info_fid", "tts"),
            ("gree_act2_fid", "tts_act2"),
            ("gree_act3_fid", "tts_act3"),
        ):
            g_low = rdef[g_fid_key] & 0x00FFFFFF
            _synthesize_single_clip(
                api_key,
                v_edid,
                rdef["voice_id"],
                g_low,
                1,
                rdef[tts_key],
                ba2_voice_map=ba2_voice_map,
            )
        h_base_low = rdef["helo_info_fid"] & 0x00FFFFFF
        _synthesize_single_clip(
            api_key,
            v_edid,
            rdef["voice_id"],
            h_base_low,
            1,
            rdef["helo_tts"],
            ba2_voice_map=ba2_voice_map,
        )
        h_base_fname = f"{h_base_low:08X}_1"
        h_base_xwm = os.path.join(v_cache_dir, f"{h_base_fname}.xwm")
        h_base_wav = os.path.join(v_cache_dir, f"{h_base_fname}.wav")
        for h_copy_key in ("helo_act2_fid", "helo_act3_fid"):
            h_low = rdef[h_copy_key] & 0x00FFFFFF
            h_fname = f"{h_low:08X}_1"
            h_xwm = os.path.join(v_cache_dir, f"{h_fname}.xwm")
            h_wav = os.path.join(v_cache_dir, f"{h_fname}.wav")
            if os.path.exists(h_base_xwm):
                shutil.copyfile(h_base_xwm, h_xwm)
            if os.path.exists(h_base_wav):
                shutil.copyfile(h_base_wav, h_wav)
            h_rel_key = f"sound\\voice\\{ESP_NAME.lower()}\\{v_edid.lower()}\\{h_fname.lower()}.xwm"
            ba2_voice_map[h_rel_key] = h_xwm

    for cdef in ACT2_WATERPLANT_CHEER_TOPICS:
        c_low = cdef["info_fid"] & 0x00FFFFFF
        _synthesize_single_clip(
            api_key,
            cdef["speaker_vtyp"],
            cdef["speaker_voice_id"],
            c_low,
            1,
            cdef["tts"],
            ba2_voice_map=ba2_voice_map,
        )

    # Generate 0.05s silent audio clip 0000407F_1 for DIAL 0x01004003 (V13Act1ResidentStopTopic)
    import wave as _wave
    stop_fname = "0000407F_1"
    for stop_vtyp in (
        V13_RES_MALE_VTYP,
        V13_RES_FEMALE_VTYP,
        VTYP_EDID,
        UNDERGROUND_LEADER_VTYP,
        SET_NECROPOLIS_VTYP,
    ):
        stop_vdir = os.path.join(VOICES_DIR, stop_vtyp)
        os.makedirs(stop_vdir, exist_ok=True)
        stop_wav = os.path.join(stop_vdir, f"{stop_fname}.wav")
        stop_xwm = os.path.join(stop_vdir, f"{stop_fname}.xwm")
        if not os.path.exists(stop_xwm):
            with _wave.open(stop_wav, "wb") as wf:
                wf.setnchannels(1)
                wf.setsampwidth(2)
                wf.setframerate(44100)
                wf.writeframes(b"\x00\x00" * 2205)
            subprocess.run(
                [XWMAENCODE_BIN, "-b", "48000", stop_wav, stop_xwm],
                check=True,
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
            )
        stop_rel_key = f"sound\\voice\\{ESP_NAME.lower()}\\{stop_vtyp.lower()}\\{stop_fname.lower()}.xwm"
        ba2_voice_map[stop_rel_key] = stop_xwm

    # Also register CrSuperMutant fallback paths in ba2_voice_map for any existing saves that cached VTCK on Harry
    harry_prefix = f"sound\\voice\\{ESP_NAME.lower()}\\{HARRY_SUPERMUTANT_VTYP.lower()}\\"
    sm_prefix = f"sound\\voice\\{ESP_NAME.lower()}\\crsupermutant\\"
    for k, v in list(ba2_voice_map.items()):
        if k.startswith(harry_prefix):
            ba2_voice_map[sm_prefix + k[len(harry_prefix):]] = v

    return ba2_voice_map


