    sp = 0
    while sp + 6 <= len(lounger_raw):
        st = lounger_raw[sp : sp + 4].decode("ascii", "ignore")
        ss = struct.unpack_from("<H", lounger_raw, sp + 4)[0]
        if st != "EDID":
            lounger_subs.extend(lounger_raw[sp : sp + 6 + ss])
        sp += 6 + ss

    def make_custom_stat_with_model(
        new_fid: int,
        edid: str,
        raw_stat: bytes,
        new_modl: str,
        obnd_vals: tuple[int, int, int, int, int, int] | None = None,
    ) -> bytes:
        s_out = bytearray()
        s_out.extend(pack_zstr("EDID", edid))
        sp_s = 0
        while sp_s + 6 <= len(raw_stat):
            st_s = raw_stat[sp_s : sp_s + 4].decode("ascii", "ignore")
            ss_s = struct.unpack_from("<H", raw_stat, sp_s + 4)[0]
            if st_s in ("EDID", "MODT"):
                pass
            elif st_s == "OBND" and obnd_vals is not None:
                s_out.extend(pack_sub("OBND", struct.pack("<6h", *obnd_vals)))
            elif st_s == "MODL":
                s_out.extend(pack_zstr("MODL", new_modl))
            else:
                s_out.extend(raw_stat[sp_s : sp_s + 6 + ss_s])
            sp_s += 6 + ss_s
        return pack_record("STAT", new_fid, bytes(s_out))

