        sp_a = 0
        wrote_attx = False
        while sp_a + 6 <= len(src_raw):
            st_a = src_raw[sp_a : sp_a + 4].decode("ascii", "ignore")
            ss_a = struct.unpack_from("<H", src_raw, sp_a + 4)[0]
            if st_a in ("EDID", "VMAD", "RADR", "ATTX", "MODT", "MODS"):
                pass
            elif st_a == "OBND":
                a_subs.extend(pack_sub("OBND", struct.pack("<6h", *obnd_vals)))
            elif st_a == "FULL":
                a_subs.extend(pack_zstr("FULL", full_name))
