    def make_custom_door(
        new_fid: int,
        edid: str,
        full_name: str,
        src_raw: bytes,
        no_npc_use: bool = True,
        model_override: str | None = None,
    ) -> bytes:
        d_subs = bytearray()
        d_subs.extend(pack_zstr("EDID", edid))
        sp_d = 0
        while sp_d + 6 <= len(src_raw):
            st_d = src_raw[sp_d : sp_d + 4].decode("ascii", "ignore")
            ss_d = struct.unpack_from("<H", src_raw, sp_d + 4)[0]
            if st_d == "EDID" or (model_override is not None and st_d == "MODT"):
                pass
            elif st_d == "FULL":
                d_subs.extend(pack_zstr("FULL", full_name))
            elif st_d == "MODL" and model_override is not None:
                d_subs.extend(pack_zstr("MODL", model_override))
            elif st_d == "FNAM" and ss_d == 1 and no_npc_use:
                f_val = src_raw[sp_d + 6] | 0x08  # 0x08 = Minimal Use (Prevents NPCs/enemies from following player through load door)
                d_subs.extend(pack_sub("FNAM", bytes([f_val])))
            else:
                d_subs.extend(src_raw[sp_d : sp_d + 6 + ss_d])
            sp_d += 6 + ss_d
        return pack_record("DOOR", new_fid, bytes(d_subs))

