    # 5. MISC: 0x01001110, 0x01001112, 0x01001113, 0x01001114, 0x01001115
    def make_quest_misc(
        new_fid: int,
        edid: str,
        full_name: str,
        script_name: str,
        model_override: str | None = None,
        featured_item: bool = False,
    ) -> bytes:
        vmad_b = build_simple_vmad(script_name)
        subs = bytearray()
        subs.extend(pack_zstr("EDID", edid))
        subs.extend(pack_sub("VMAD", vmad_b))
        sp_m = 0
        while sp_m + 6 <= len(misc_raw):
            st_m = misc_raw[sp_m : sp_m + 4].decode("ascii", "ignore")
            ss_m = struct.unpack_from("<H", misc_raw, sp_m + 4)[0]
            if st_m == "EDID":
                pass
            elif st_m in ("KSIZ", "KWDA") and not featured_item:
                pass
            elif st_m == "MODT" and model_override:
                pass
            elif st_m == "MODL" and model_override:
                subs.extend(pack_zstr("MODL", model_override))
            elif st_m == "FULL":
                subs.extend(pack_zstr("FULL", full_name))
            elif st_m == "DATA":
                subs.extend(pack_sub("DATA", struct.pack("<If", 500, 0.5)))
            else:
                subs.extend(misc_raw[sp_m : sp_m + 6 + ss_m])
            sp_m += 6 + ss_m
        return pack_record("MISC", new_fid, bytes(subs))

