    # 6. CONT: 0x01001120..0x0100112A, 0x01001178
    def make_cont_rec(
        new_fid: int,
        edid: str,
        full_name: str,
        raw_bytes: bytes,
        items: list[tuple[int, int]] | None = None,
        script_name: str | None = None,
        custom_modl: str | None = None,
    ) -> bytes:
        out = bytearray()
        out.extend(pack_zstr("EDID", edid))
        if script_name:
            out.extend(pack_sub("VMAD", build_simple_vmad(script_name)))
        sp_c = 0
        wrote_items = False
        while sp_c + 6 <= len(raw_bytes):
            st_c = raw_bytes[sp_c : sp_c + 4].decode("ascii", "ignore")
            ss_c = struct.unpack_from("<H", raw_bytes, sp_c + 4)[0]
            sv_c = raw_bytes[sp_c + 6 : sp_c + 6 + ss_c]
            if st_c in ("EDID", "VMAD", "PTRN", "COCT", "CNTO"):
                pass
            elif st_c == "FULL":
                out.extend(pack_zstr("FULL", full_name))
            elif st_c == "MODL" and custom_modl:
                out.extend(pack_zstr("MODL", custom_modl))
            elif st_c == "DATA":
                if items and not wrote_items:
                    out.extend(pack_sub("COCT", struct.pack("<I", len(items))))
                    for ifid, icnt in items:
                        out.extend(pack_sub("CNTO", struct.pack("<II", ifid, icnt)))
                    wrote_items = True
                out.extend(pack_sub("DATA", b"\x00" + sv_c[1:]))
            else:
                out.extend(raw_bytes[sp_c : sp_c + 6 + ss_c])
            sp_c += 6 + ss_c
        return pack_record("CONT", new_fid, bytes(out))

