    # 7. TERM: 0x01001130..0x0100113F
    _, _, _, term_raw = tpl["term_desk"]
    _, _, _, term_wall_raw = tpl["term_wall"]

    def make_custom_term(
        new_fid: int,
        edid: str,
        full_name: str,
        header_txt: str,
        entries: list,
        script_name: str | None = None,
        src_term_raw: bytes = term_raw,
    ) -> bytes:
        is_wall = src_term_raw is term_wall_raw
        t_subs = bytearray()
        t_subs.extend(pack_zstr("EDID", edid))
        if script_name:
            t_subs.extend(pack_sub("VMAD", build_simple_vmad(script_name)))
        sp_t = 0
        while sp_t + 6 <= len(term_raw):
            st_t = term_raw[sp_t : sp_t + 4].decode("ascii", "ignore")
            ss_t = struct.unpack_from("<H", term_raw, sp_t + 4)[0]
            if st_t in (
                "EDID",
                "VMAD",
                "NAM0",
                "WNAM",
                "FULL",
                "BTXT",
                "ISIZ",
                "ITXT",
                "ANAM",
                "ITID",
                "UNAM",
                "RNAM",
                "TNAM",
            ):
                pass
            elif st_t == "OBND":
                if is_wall:
                    t_subs.extend(
                        pack_sub("OBND", b"\xee\xff\xcc\xffV\x00\x15\x00\x00\x00\x87\x00")
                    )
                else:
                    t_subs.extend(term_raw[sp_t : sp_t + 6 + ss_t])
                t_subs.extend(pack_zstr("NAM0", "SISTEMA CENTRAL VAULT-TEC — CALIFORNIA (2161)"))
                t_subs.extend(pack_zstr("WNAM", header_txt))
            elif st_t == "MODL" and is_wall:
                t_subs.extend(pack_zstr("MODL", "Furniture\\Terminals\\TerminalWall01.nif"))
            elif st_t == "KWDA" and is_wall:
                t_subs.extend(
                    pack_sub("KWDA", struct.pack("<3I", 0x000A56D7, 0x0006D5BB, 0x000C2022))
                )
            elif st_t == "SNAM" and is_wall:
                t_subs.extend(
                    pack_sub(
                        "SNAM",
                        b"\x00\x00\x00\x00\x00\x00\xac\xc2\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\xff\xff\xff\xff",
                    )
                )
            elif st_t == "BSIZ":
                t_subs.extend(pack_zstr("FULL", full_name))
                t_subs.extend(pack_sub("BSIZ", struct.pack("<I", 0)))
                t_subs.extend(pack_sub("ISIZ", struct.pack("<I", len(entries))))
                for idx_e, entry_item in enumerate(entries, 1):
                    itxt_s = entry_item[0]
                    unam_s = entry_item[1]
                    item_id = entry_item[2] if len(entry_item) > 2 else idx_e
                    ctda_list = entry_item[3] if len(entry_item) > 3 else []
                    t_subs.extend(pack_zstr("ITXT", itxt_s))
                    t_subs.extend(pack_zstr("RNAM", itxt_s))
                    t_subs.extend(pack_sub("ANAM", b"\x08"))
                    t_subs.extend(pack_sub("ITID", struct.pack("<H", item_id)))
                    t_subs.extend(pack_zstr("UNAM", unam_s))
                    for ctda_b in ctda_list:
                        t_subs.extend(pack_sub("CTDA", ctda_b))
            else:
                t_subs.extend(term_raw[sp_t : sp_t + 6 + ss_t])
            sp_t += 6 + ss_t
        return pack_record("TERM", new_fid, bytes(t_subs))

