    # 8. BOOK: 0x01001140..0x0100114E
    def make_dossier_book(new_fid: int, edid: str, full_name: str, desc_txt: str) -> bytes:
        b_subs = (
            pack_zstr("EDID", edid)
            + pack_sub("OBND", struct.pack("<6h", -13, -19, 0, 14, 0, 0))
            + pack_sub("PTRN", bytes.fromhex("26f01c00"))
            + pack_zstr("FULL", full_name)
            + pack_zstr("MODL", "SetDressing\\Office\\FolderPapers02.nif")
            + pack_sub(
                "MODT",
                bytes.fromhex(
                    "040000000300000000000000010000000100000098fe011364647300514b8577"
                    "4192077064647300514b857706c5949264647300514b8577f0d123226267736d"
                    "e25d598b"
                ),
            )
            + pack_zstr("DESC", desc_txt)
            + pack_sub("DATA", struct.pack("<If", 100, 0.2))
            + pack_sub("DNAM", bytes(13))
            + pack_sub("INAM", bytes.fromhex("7d0d1400"))
        )
        return pack_record("BOOK", new_fid, b_subs)

