    # 9. WEAP: 0x01001102, 0x01001105, 0x01001108, 0x0100110B, 0x0100110E, 0x0100110F, 0x01001117
    def make_custom_weap(
        new_fid: int,
        edid: str,
        full_name: str,
        desc_txt: str,
        ench_fid: int,
        src_raw: bytes,
        val_gold: int,
        base_dmg: int,
        energy_dmg: int | None = None,
        attach_item_script: bool = False,
        custom_obts: bytes | None = None,
    ) -> bytes:
        first_obts = custom_obts if custom_obts is not None else b""
        if not first_obts:
            sp_scan = 0
            while sp_scan + 6 <= len(src_raw):
                st_s = src_raw[sp_scan : sp_scan + 4].decode("ascii", "ignore")
                ss_s = struct.unpack_from("<H", src_raw, sp_scan + 4)[0]
                if st_s == "OBTS":
                    first_obts = src_raw[sp_scan + 6 : sp_scan + 6 + ss_s]
                    break
                sp_scan += 6 + ss_s

        w_subs = bytearray()
        w_subs.extend(pack_zstr("EDID", edid))
        if attach_item_script:
            w_subs.extend(pack_sub("VMAD", build_simple_vmad("V13ItemRadscorpionGlandScript")))
        sp_w = 0
        skip_ob = False
        while sp_w + 6 <= len(src_raw):
            st_w = src_raw[sp_w : sp_w + 4].decode("ascii", "ignore")
            ss_w = struct.unpack_from("<H", src_raw, sp_w + 4)[0]
            sv_w = bytearray(src_raw[sp_w + 6 : sp_w + 6 + ss_w])
            if st_w in ("EDID", "EITM") or (st_w == "VMAD" and attach_item_script):
                pass
            elif st_w == "FULL" and not skip_ob:
                w_subs.extend(pack_zstr("FULL", full_name))
                w_subs.extend(pack_sub("EITM", struct.pack("<I", ench_fid)))
            elif st_w == "DESC":
                w_subs.extend(pack_zstr("DESC", desc_txt))
            elif st_w == "OBTE":
                skip_ob = True
                w_subs.extend(pack_sub("OBTE", struct.pack("<I", 1)))
                w_subs.extend(pack_sub("OBTF", b""))
                if first_obts:
                    w_subs.extend(pack_sub("OBTS", first_obts))
                w_subs.extend(pack_sub("STOP", b""))
            elif skip_ob:
                if st_w == "STOP":
                    skip_ob = False
            elif st_w == "DAMA" and ss_w == 8 and energy_dmg is not None:
                w_subs.extend(pack_sub("DAMA", struct.pack("<II", 0x00060A81, energy_dmg)))
            elif st_w == "DNAM" and ss_w == 132:
                struct.pack_into("<IH", sv_w, 63, val_gold, base_dmg)
                w_subs.extend(pack_sub("DNAM", bytes(sv_w)))
            else:
                w_subs.extend(src_raw[sp_w : sp_w + 6 + ss_w])
            sp_w += 6 + ss_w
        return pack_record("WEAP", new_fid, bytes(w_subs))

