    # 9b. ARMO: 0x01001301..0x01001306 (Hardened T-51b/Mk.VI Power Armor) + 0x01001307 (Vault 13 Jumpsuit)
    def make_v13_pa_piece(
        new_fid: int,
        edid: str,
        full_name: str,
        desc_txt: str,
        raw_bytes: bytes,
        omod_list: list[int],
    ) -> bytes:
        pa_obts = bytearray.fromhex("000000000000000000000000ffff01000000")
        pa_obts[0] = len(omod_list)
        for omod_fid in omod_list:
            pa_obts.extend(struct.pack("<I", omod_fid) + b"\x00\x00\x01")
        subs = bytearray()
        subs.extend(pack_zstr("EDID", edid))
        sp_a = 0
        skip_ob = False
        while sp_a + 6 <= len(raw_bytes):
            st_a = raw_bytes[sp_a : sp_a + 4].decode("ascii", "ignore")
            ss_a = struct.unpack_from("<H", raw_bytes, sp_a + 4)[0]
            if st_a == "EDID":
                pass
            elif st_a == "FULL" and not skip_ob:
                subs.extend(pack_zstr("FULL", full_name))
            elif st_a == "DESC":
                subs.extend(pack_zstr("DESC", desc_txt))
            elif st_a == "OBTE":
                skip_ob = True
                subs.extend(pack_sub("OBTE", struct.pack("<I", 1)))
                subs.extend(pack_sub("OBTS", bytes(pa_obts)))
                subs.extend(pack_sub("OBTF", b""))
                subs.extend(pack_sub("STOP", b""))
            elif skip_ob:
                if st_a == "STOP":
                    skip_ob = False
            else:
                subs.extend(raw_bytes[sp_a : sp_a + 6 + ss_a])
            sp_a += 6 + ss_a
        return pack_record("ARMO", new_fid, bytes(subs))

    _, _, _, v81_suit_raw = tpl["armo_vault81_suit"]

    def make_v13_vaultsuit_arma(new_fid: int, edid: str, src_arma_raw: bytes, mswp_fid: int) -> bytes:
        subs = bytearray()
        subs.extend(pack_zstr("EDID", edid))
        sp_va = 0
        while sp_va + 6 <= len(src_arma_raw):
            st_va = src_arma_raw[sp_va : sp_va + 4].decode("ascii", "ignore")
            ss_va = struct.unpack_from("<H", src_arma_raw, sp_va + 4)[0]
            if st_va == "EDID":
                pass
            elif st_va in ("MO2S", "MO3S"):
                subs.extend(pack_sub(st_va, struct.pack("<I", mswp_fid)))
            elif st_va == "MO4T":
                subs.extend(src_arma_raw[sp_va : sp_va + 6 + ss_va])
                subs.extend(pack_sub("MO4S", struct.pack("<I", mswp_fid)))
            elif st_va == "MO5T":
                subs.extend(src_arma_raw[sp_va : sp_va + 6 + ss_va])
                subs.extend(pack_sub("MO5S", struct.pack("<I", mswp_fid)))
            else:
                subs.extend(src_arma_raw[sp_va : sp_va + 6 + ss_va])
            sp_va += 6 + ss_va
        return pack_record("ARMA", new_fid, bytes(subs))

    def build_v13_jumpsuit_armo_subs(
        edid: str, full_name: str, desc_txt: str, arma_fid: int, mswp_fid: int
    ) -> bytes:
        out_subs = bytearray()
        out_subs.extend(pack_zstr("EDID", edid))
        sp_js = 0
        while sp_js + 6 <= len(v81_suit_raw):
            st_js = v81_suit_raw[sp_js : sp_js + 4].decode("ascii", "ignore")
            ss_js = struct.unpack_from("<H", v81_suit_raw, sp_js + 4)[0]
            if st_js in ("EDID", "MO2S", "MO4S"):
                pass
            elif st_js == "FULL":
                out_subs.extend(pack_zstr("FULL", full_name))
            elif st_js == "DESC":
                out_subs.extend(pack_zstr("DESC", desc_txt))
            elif st_js == "MO2T":
                out_subs.extend(v81_suit_raw[sp_js : sp_js + 6 + ss_js])
                out_subs.extend(pack_sub("MO2S", struct.pack("<I", mswp_fid)))
            elif st_js == "MO4T":
                out_subs.extend(v81_suit_raw[sp_js : sp_js + 6 + ss_js])
                out_subs.extend(pack_sub("MO4S", struct.pack("<I", mswp_fid)))
            elif st_js == "MODL" and ss_js == 4:
                out_subs.extend(pack_sub("MODL", struct.pack("<I", arma_fid)))
            elif st_js == "OBTS":
                obts_pay = v81_suit_raw[sp_js + 6 : sp_js + 6 + ss_js].replace(
                    struct.pack("<I", 0x0022DA6D), struct.pack("<I", mswp_fid)
                )
                out_subs.extend(pack_sub("OBTS", obts_pay))
            else:
                out_subs.extend(v81_suit_raw[sp_js : sp_js + 6 + ss_js])
            sp_js += 6 + ss_js
        return bytes(out_subs)

