    def make_v13_custom_arma(
        new_fid: int,
        edid: str,
        src_arma_raw: bytes,
        mod2_rel: str,
        mod3_rel: str,
    ) -> bytes:
        subs = bytearray()
        subs.extend(pack_zstr("EDID", edid))
        sp_a = 0
        while sp_a + 6 <= len(src_arma_raw):
            st_a = src_arma_raw[sp_a : sp_a + 4].decode("ascii", "ignore")
            ss_a = struct.unpack_from("<H", src_arma_raw, sp_a + 4)[0]
            if st_a in ("EDID", "MO2T", "MO2F", "MO2S", "MO3T", "MO3F", "MO3S"):
                pass
            elif st_a == "MOD2":
                subs.extend(pack_zstr("MOD2", mod2_rel))
            elif st_a == "MOD3":
                subs.extend(pack_zstr("MOD3", mod3_rel))
            else:
                subs.extend(src_arma_raw[sp_a : sp_a + 6 + ss_a])
            sp_a += 6 + ss_a
        return pack_record("ARMA", new_fid, bytes(subs))

    def make_v13_custom_headgear_armo(
        new_fid: int,
        edid: str,
        full_name: str,
        desc_txt: str,
        src_armo_raw: bytes,
        arma_fid: int,
        go_nif_rel: str,
    ) -> bytes:
        subs = bytearray()
        subs.extend(pack_zstr("EDID", edid))
        sp_m = 0
        in_obte = False
        wrote_indx_modl = False
        while sp_m + 6 <= len(src_armo_raw):
            st_m = src_armo_raw[sp_m : sp_m + 4].decode("ascii", "ignore")
            ss_m = struct.unpack_from("<H", src_armo_raw, sp_m + 4)[0]
            if st_m == "OBTE":
                in_obte = True
            elif st_m == "STOP":
                in_obte = False
            elif in_obte or st_m in ("EDID", "MO2T", "MO2S", "MO4T", "MO4S", "APPR", "INRD"):
                pass
            elif st_m == "FULL":
                subs.extend(pack_zstr("FULL", full_name))
            elif st_m == "DESC":
                subs.extend(pack_zstr("DESC", desc_txt))
            elif st_m == "MOD2":
                subs.extend(pack_zstr("MOD2", go_nif_rel))
            elif st_m == "MOD4":
                subs.extend(pack_zstr("MOD4", go_nif_rel))
            elif st_m in ("INDX", "MODL"):
                if not wrote_indx_modl:
                    subs.extend(pack_sub("INDX", struct.pack("<H", 0)))
                    subs.extend(pack_sub("MODL", struct.pack("<I", arma_fid)))
                    wrote_indx_modl = True
            else:
                subs.extend(src_armo_raw[sp_m : sp_m + 6 + ss_m])
            sp_m += 6 + ss_m
        return pack_record("ARMO", new_fid, bytes(subs))

    def make_v13_raiderdog_skin_arma(new_fid: int, edid: str, src_arma_raw: bytes) -> bytes:
        subs = bytearray()
        subs.extend(pack_zstr("EDID", edid))
        sp_a = 0
        wrote_extra_races = False
        while sp_a + 6 <= len(src_arma_raw):
            st_a = src_arma_raw[sp_a : sp_a + 4].decode("ascii", "ignore")
            ss_a = struct.unpack_from("<H", src_arma_raw, sp_a + 4)[0]
            if st_a == "EDID":
                pass
            elif st_a == "SNDD" and not wrote_extra_races:
                subs.extend(pack_sub("MODL", struct.pack("<I", 0x0001D698)))  # DogmeatRace (savegame fallback)
                subs.extend(pack_sub("MODL", struct.pack("<I", 0x0003578A)))  # ViciousDogRace
                wrote_extra_races = True
                subs.extend(src_arma_raw[sp_a : sp_a + 6 + ss_a])
            else:
                subs.extend(src_arma_raw[sp_a : sp_a + 6 + ss_a])
            sp_a += 6 + ss_a
        if not wrote_extra_races:
            subs.extend(pack_sub("MODL", struct.pack("<I", 0x0001D698)))
            subs.extend(pack_sub("MODL", struct.pack("<I", 0x0003578A)))
        return pack_record("ARMA", new_fid, bytes(subs))

    def make_v13_raiderdog_skin_armo(
        new_fid: int, edid: str, src_armo_raw: bytes, arma_fid: int
    ) -> bytes:
        subs = bytearray()
        subs.extend(pack_zstr("EDID", edid))
        sp_m = 0
        while sp_m + 6 <= len(src_armo_raw):
            st_m = src_armo_raw[sp_m : sp_m + 4].decode("ascii", "ignore")
            ss_m = struct.unpack_from("<H", src_armo_raw, sp_m + 4)[0]
            if st_m == "EDID":
                pass
            elif st_m == "MODL":
                subs.extend(pack_sub("MODL", struct.pack("<I", arma_fid)))
            else:
                subs.extend(src_armo_raw[sp_m : sp_m + 6 + ss_m])
            sp_m += 6 + ss_m
        return pack_record("ARMO", new_fid, bytes(subs), flags=0x00000004)

