    _, _, _, forsythe_raw = tpl["npc_forsythe"]
    jacoren_subs = bytearray()
    jacoren_subs.extend(pack_zstr("EDID", "NPC_V13_OverseerJacoren"))
    sp = 0
    wrote_pkid = False
    wrote_snam = False
    while sp + 6 <= len(forsythe_raw):
        st = forsythe_raw[sp : sp + 4].decode("ascii", "ignore")
        ss = struct.unpack_from("<H", forsythe_raw, sp + 4)[0]
        sv = bytearray(forsythe_raw[sp + 6 : sp + 6 + ss])
        if st in ("EDID", "CRIF"):
            pass
        elif st == "ACBS" and ss >= 4:
            flags_acbs = struct.unpack_from("<I", sv, 0)[0]
            flags_acbs |= 0x00000022
            struct.pack_into("<I", sv, 0, flags_acbs)
            if ss >= 16:
                struct.pack_into("<H", sv, 14, 0)
            jacoren_subs.extend(pack_sub("ACBS", bytes(sv)))
        elif st == "SNAM":
            if not wrote_snam:
                jacoren_subs.extend(pack_sub("SNAM", struct.pack("<IB", 0x0001C21C, 0)))
                wrote_snam = True
        elif st == "VTCK":
            jacoren_subs.extend(pack_sub("VTCK", struct.pack("<I", 0x01001001)))
        elif st == "PKID":
            if not wrote_pkid:
                jacoren_subs.extend(pack_sub("PKID", struct.pack("<I", 0x01001050)))
                jacoren_subs.extend(pack_sub("PKID", struct.pack("<I", 0x0023EC8E)))
                wrote_pkid = True
        elif st == "FULL":
            jacoren_subs.extend(pack_zstr("FULL", "Supervisor Jacoren"))
        elif st == "SHRT":
            jacoren_subs.extend(pack_zstr("SHRT", "Jacoren"))
        elif st == "DOFT":
            jacoren_subs.extend(pack_sub("DOFT", struct.pack("<I", 0x01001010)))
        else:
            jacoren_subs.extend(forsythe_raw[sp : sp + 6 + ss])
        sp += 6 + ss
    jacoren_comp = zlib.compress(bytes(jacoren_subs))
    npc_jacoren_rec = pack_record(
        "NPC_", 0x01001200, struct.pack("<I", len(jacoren_subs)) + jacoren_comp, flags=0x00040000
    )

