    def make_enemy_npc(
        new_fid: int,
        edid: str,
        full_name: str,
        level_val: int,
        hp_val: float,
        inv_items: list[tuple[int, int]] | None,
        outfit_fid: int | None,
        src_npc_raw: bytes = raider_raw,
        preserve_obte: bool = False,
        scale_min: float | None = None,
        scale_max: float | None = None,
        initially_unaggressive: bool = False,
    ) -> bytes:
        out = bytearray()
        out.extend(pack_zstr("EDID", edid))
        attach_ai_script = (not initially_unaggressive) and (new_fid != 0x01001224)
        if attach_ai_script:
            out.extend(pack_sub("VMAD", build_simple_vmad("V13WastelandCreatureAIScript", [])))
        sp_r = 0
        wrote_cnto = False
        wrote_snam = False
        wrote_pkid = False
        in_obte = False
        while sp_r + 6 <= len(src_npc_raw):
            st_r = src_npc_raw[sp_r : sp_r + 4].decode("ascii", "ignore")
            ss_r = struct.unpack_from("<H", src_npc_raw, sp_r + 4)[0]
            sv_r = bytearray(src_npc_raw[sp_r + 6 : sp_r + 6 + ss_r])
            if st_r == "OBTE":
                in_obte = True
                if preserve_obte:
                    out.extend(src_npc_raw[sp_r : sp_r + 6 + ss_r])
            elif st_r == "STOP":
                in_obte = False
                if preserve_obte:
                    out.extend(src_npc_raw[sp_r : sp_r + 6 + ss_r])
            elif in_obte:
                if preserve_obte:
                    out.extend(src_npc_raw[sp_r : sp_r + 6 + ss_r])
            elif st_r in ("EDID", "TPLT", "TPTA", "PKID"):
                pass
            elif st_r == "VMAD" and attach_ai_script:
                pass
            elif st_r == "VTCK" and new_fid in (0x01001203, 0x0100125E):
                out.extend(pack_sub("VTCK", struct.pack("<I", 0x01001009)))
            elif st_r == "SNAM" and (preserve_obte or initially_unaggressive):
                if not wrote_snam:
                    if new_fid == 0x0100125E:
                        # Dying Super Mutant (Tug) has no faction so nearby Deathclaw and companions treat him as Neutral
                        wrote_snam = True
                    elif initially_unaggressive and src_npc_raw is sm_raw:
                        out.extend(pack_sub("SNAM", struct.pack("<IB", 0x00058305, 0)))
                        wrote_snam = True
                    elif not initially_unaggressive:
                        out.extend(pack_sub("SNAM", struct.pack("<IB", 0x0001CBED, 0)))
                        wrote_snam = True
            elif st_r == "WNAM":
                out.extend(src_npc_raw[sp_r : sp_r + 6 + ss_r])
                if new_fid in (0x01001252, 0x0100125D):
                    out.extend(pack_sub("ATKR", struct.pack("<I", 0x0001DB4A)))
            elif st_r == "ACBS" and ss_r >= 4:
                fl_a = struct.unpack_from("<I", sv_r, 0)[0]
                fl_a &= ~0x0000080A
                if initially_unaggressive:
                    fl_a |= 0x00000020
                if new_fid in (
                    0x01001201,
                    0x01001203,
                    0x01001238,
                    0x01001244,
                    0x01001248,
                    0x0100124B,
                    0x0100124E,
                    0x01001252,
                    0x0100125D,
                    0x0100125E,
                ):
                    fl_a |= 0x00000820  # Unique (0x20) + Protected (0x800, only player can kill quest bosses)
                struct.pack_into("<I", sv_r, 0, fl_a)
                struct.pack_into("<H", sv_r, 6, level_val)
                if ss_r >= 16:
                    struct.pack_into("<H", sv_r, 14, 0)  # Clear Use-Template flags (offset 14) when TPLT is stripped
                out.extend(pack_sub("ACBS", bytes(sv_r)))
            elif st_r == "AIDT" and ss_r >= 4:
                if inv_items is not None and not wrote_cnto:
                    out.extend(pack_sub("COCT", struct.pack("<I", len(inv_items))))
                    for i_fid, i_cnt in inv_items:
                        out.extend(pack_sub("CNTO", struct.pack("<II", i_fid, i_cnt)))
                    wrote_cnto = True
                if initially_unaggressive:
                    sv_r[0] = 0  # Unaggressive until combat is triggered via script (prevents premature/friendly fire)
                    sv_r[1] = 4  # Foolhardy (never cowers/flees, fights immediately when in combat)
                    sv_r[3] = 2  # Helps Friends and Allies
                else:
                    sv_r[0] = 2  # Very Aggressive (attacks Enemies and Neutrals on sight)
                    sv_r[1] = 4  # Foolhardy
                out.extend(pack_sub("AIDT", bytes(sv_r)))
                if not wrote_pkid:
                    if new_fid == 0x0100125E:
                        out.extend(pack_sub("PKID", struct.pack("<I", 0x01001051)))
                        out.extend(pack_sub("PKID", struct.pack("<I", 0x01001050)))
                    elif new_fid in (0x01001224, 0x01001253, 0x01001254, 0x01001265):
                        out.extend(pack_sub("PKID", struct.pack("<I", 0x01001050)))
                        out.extend(pack_sub("PKID", struct.pack("<I", 0x00042A1C)))
                    elif new_fid == 0x01001256:
                        # Petrox's Khan kidnap guards hold camp position without furniture or Vault 12 evacuation
                        out.extend(pack_sub("PKID", struct.pack("<I", 0x01001054)))
                        out.extend(pack_sub("PKID", struct.pack("<I", 0x01001050)))
                        out.extend(pack_sub("PKID", struct.pack("<I", 0x00042A1C)))
                    elif initially_unaggressive:
                        # Interior Watershed Super Mutants (Harry, Barry, Sally & Watershed Guard)
                        out.extend(pack_sub("PKID", struct.pack("<I", 0x01001053)))
                        out.extend(pack_sub("PKID", struct.pack("<I", 0x01001054)))
                        out.extend(pack_sub("PKID", struct.pack("<I", 0x01001050)))
                        out.extend(pack_sub("PKID", struct.pack("<I", 0x00042A1C)))
                    else:
                        # Furniture-free guard hold at current post + DefaultMasterPackage (prevents seeking chairs/cots inside closed exterior houses)
                        out.extend(pack_sub("PKID", struct.pack("<I", 0x01001050)))
                        out.extend(pack_sub("PKID", struct.pack("<I", 0x00042A1C)))
                    wrote_pkid = True
            elif st_r == "PRPS" and ss_r >= 8:
                wrote_hp = False
                for off_p in range(0, ss_r - 7, 8):
                    av_id = struct.unpack_from("<I", sv_r, off_p)[0]
                    if av_id == 0x000002DA:
                        struct.pack_into("<f", sv_r, off_p + 4, 100.0)
                    elif av_id == 0x000002D4:
                        struct.pack_into("<f", sv_r, off_p + 4, hp_val)
                        wrote_hp = True
                    elif av_id == 0x000002C3:
                        struct.pack_into("<f", sv_r, off_p + 4, 80.0)
                if not wrote_hp:
                    sv_r.extend(struct.pack("<If", 0x000002D4, hp_val))
                out.extend(pack_sub("PRPS", bytes(sv_r)))
            elif st_r == "NAM6" and scale_min is not None and not in_obte:
                out.extend(pack_sub("NAM6", struct.pack("<f", scale_min)))
            elif st_r == "NAM4" and scale_max is not None and not in_obte:
                out.extend(pack_sub("NAM4", struct.pack("<f", scale_max)))
            elif st_r in ("COCT", "CNTO") and inv_items is not None:
                if not wrote_cnto:
                    out.extend(pack_sub("COCT", struct.pack("<I", len(inv_items))))
                    for i_fid, i_cnt in inv_items:
                        out.extend(pack_sub("CNTO", struct.pack("<II", i_fid, i_cnt)))
                    wrote_cnto = True
            elif st_r == "FULL" and not in_obte:
                out.extend(pack_zstr("FULL", full_name))
                if new_fid == 0x01001203:
                    out.extend(pack_zstr("SHRT", "Harry"))
                elif new_fid == 0x0100125E:
                    out.extend(pack_zstr("SHRT", "Tug"))
                elif new_fid == 0x01001262:
                    out.extend(pack_zstr("SHRT", "Barry"))
                elif new_fid == 0x01001263:
                    out.extend(pack_zstr("SHRT", "Sally"))
            elif st_r == "DOFT" and outfit_fid is not None:
                out.extend(pack_sub("DOFT", struct.pack("<I", outfit_fid)))
            else:
                out.extend(src_npc_raw[sp_r : sp_r + 6 + ss_r])
            sp_r += 6 + ss_r
        comp_r = zlib.compress(bytes(out))
        return pack_record("NPC_", new_fid, struct.pack("<I", len(out)) + comp_r, flags=0x00040000)

    turret_subs = bytearray()
    turret_subs.extend(pack_zstr("EDID", "NPC_V13_UnityDefenseTurret"))
    sp_t = 0
    while sp_t + 6 <= len(turret_raw):
        st_t = turret_raw[sp_t : sp_t + 4].decode("ascii", "ignore")
        ss_t = struct.unpack_from("<H", turret_raw, sp_t + 4)[0]
        sv_t = bytearray(turret_raw[sp_t + 6 : sp_t + 6 + ss_t])
        if st_t in ("EDID", "TPLT", "TPTA"):
            pass
        elif st_t == "ACBS" and ss_t >= 4:
            fl_t = struct.unpack_from("<I", sv_t, 0)[0]
            fl_t &= ~0x00000008
            struct.pack_into("<I", sv_t, 0, fl_t)
            struct.pack_into("<H", sv_t, 6, 12)
            if ss_t >= 16:
                struct.pack_into("<H", sv_t, 14, 0)
            turret_subs.extend(pack_sub("ACBS", bytes(sv_t)))
        elif st_t == "FULL":
            turret_subs.extend(pack_zstr("FULL", "Torreta Láser Automatizada de la Unidad"))
        elif st_t == "SHRT":
            turret_subs.extend(pack_zstr("SHRT", "Torreta Láser"))
        else:
            turret_subs.extend(turret_raw[sp_t : sp_t + 6 + ss_t])
        sp_t += 6 + ss_t
    comp_turret = zlib.compress(bytes(turret_subs))
    npc_turret_rec = pack_record(
        "NPC_", 0x0100120C, struct.pack("<I", len(turret_subs)) + comp_turret, flags=0x00040000
    )

    def make_friendly_v13_npc(rdef: dict) -> bytes:
        _, _, _, raw_npc = tpl[rdef["tpl_key"]]
        out = bytearray()
        out.extend(pack_zstr("EDID", rdef["edid"]))
        sp_n = 0
        wrote_snam = False
        wrote_pkid = False
        wrote_cnto = False
        wrote_full = False
        wrote_shrt = False
        fmrs_idx = 0
        inv_items = rdef["inv_items"]
        while sp_n + 6 <= len(raw_npc):
            st_n = raw_npc[sp_n : sp_n + 4].decode("ascii", "ignore")
            ss_n = struct.unpack_from("<H", raw_npc, sp_n + 4)[0]
            sv_n = bytearray(raw_npc[sp_n + 6 : sp_n + 6 + ss_n])
            if st_n in ("EDID", "VMAD", "CRIF", "TPLT", "TPTA"):
                pass
            elif st_n == "OBND":
                out.extend(pack_sub("OBND", b"\xea\xff\xf2\xff\x00\x00\x16\x00\x0e\x00\x80\x00"))
            elif st_n == "ACBS" and ss_n >= 4:
                fl_n = struct.unpack_from("<I", sv_n, 0)[0]
                if rdef.get("killable"):
                    fl_n |= 0x00000820  # Unique (0x20) + Protected (0x800, only player can kill)
                    fl_n &= ~0x0000000A # Clear Essential (0x02) and Respawn (0x08)
                else:
                    fl_n |= 0x00000822  # Essential (0x02) + Unique (0x20) + Protected (0x800)
                    fl_n &= ~0x00000008
                struct.pack_into("<I", sv_n, 0, fl_n)
                if ss_n >= 16:
                    struct.pack_into("<H", sv_n, 14, 0)
                out.extend(pack_sub("ACBS", bytes(sv_n)))
            elif st_n == "SNAM":
                if not wrote_snam:
                    if not rdef.get("killable"):
                        out.extend(pack_sub("SNAM", struct.pack("<IB", 0x0001C21C, 0)))
                    if rdef.get("is_companion"):
                        out.extend(pack_sub("SNAM", struct.pack("<IB", 0x00106C30, 0)))
                    if rdef.get("vendor_fact_fid"):
                        out.extend(pack_sub("SNAM", struct.pack("<IB", rdef["vendor_fact_fid"], 0)))
                    wrote_snam = True
            elif st_n == "AIDT" and ss_n >= 4:
                if rdef.get("is_companion") and ss_n >= 6:
                    sv_n[0] = 0    # Unaggressive until recruited
                    sv_n[1] = 4    # Foolhardy (Confidence = 4.0 >= 2.5 -> holds home position until recruited)
                    sv_n[2] = 100  # Energy
                    sv_n[3] = 0    # Morality
                    sv_n[5] = 2    # Assistance = Helps Friends and Allies
                else:
                    sv_n[0] = 0  # Unaggressive (friendly townsfolk never auto-initiate exterior wilderness combat)
                    sv_n[3] = 0  # Does not chain-pull distant exterior combat alarms
                out.extend(pack_sub("AIDT", bytes(sv_n)))
            elif st_n == "VTCK":
                out.extend(pack_sub("VTCK", struct.pack("<I", rdef["vtyp_fid"])))
            elif st_n == "PKID":
                if not wrote_pkid:
                    if rdef.get("is_companion"):
                        out.extend(pack_sub("PKID", struct.pack("<I", 0x01001055)))  # V13DogmeatCloseFollowPack (active when Confidence < 2.5)
                        out.extend(pack_sub("PKID", struct.pack("<I", 0x01001050)))  # V13StayAtCurrentPositionPack (default hold position)
                        out.extend(pack_sub("PKID", struct.pack("<I", 0x0023EC8E)))
                    elif rdef.get("custom_pkids"):
                        for pk_fid in rdef["custom_pkids"]:
                            out.extend(pack_sub("PKID", struct.pack("<I", pk_fid)))
                    elif rdef.get("stay_at_pos"):
                        out.extend(pack_sub("PKID", struct.pack("<I", 0x01001050)))
                        out.extend(pack_sub("PKID", struct.pack("<I", 0x0023EC8E)))
                    else:
                        out.extend(pack_sub("PKID", struct.pack("<I", 0x00043A7A)))
                        out.extend(pack_sub("PKID", struct.pack("<I", 0x00107AEA)))
                        out.extend(pack_sub("PKID", struct.pack("<I", 0x00089605)))
                    wrote_pkid = True
            elif st_n in ("COCT", "CNTO"):
                if inv_items is not None and not wrote_cnto:
                    out.extend(pack_sub("COCT", struct.pack("<I", len(inv_items))))
                    for i_fid, i_cnt in inv_items:
                        out.extend(pack_sub("CNTO", struct.pack("<II", i_fid, i_cnt)))
                    wrote_cnto = True
            elif st_n == "FULL":
                out.extend(pack_zstr("FULL", rdef["full"]))
                wrote_full = True
            elif st_n == "SHRT":
                out.extend(pack_zstr("SHRT", rdef["shrt"]))
                wrote_shrt = True
            elif st_n == "DATA":
                if not wrote_full:
                    out.extend(pack_zstr("FULL", rdef["full"]))
                    wrote_full = True
                if not wrote_shrt:
                    out.extend(pack_zstr("SHRT", rdef["shrt"]))
                    wrote_shrt = True
                out.extend(raw_npc[sp_n : sp_n + 6 + ss_n])
            elif st_n == "HCLF" and rdef.get("hcl_fid"):
                out.extend(pack_sub("HCLF", struct.pack("<I", rdef["hcl_fid"])))
            elif st_n == "DOFT":
                out.extend(pack_sub("DOFT", struct.pack("<I", rdef["outfit_fid"])))
            elif st_n == "MWGT" and rdef.get("mwgt"):
                w_thin, w_musc, w_fat = rdef["mwgt"]
                out.extend(pack_sub("MWGT", struct.pack("<3f", w_thin, w_musc, w_fat)))
            elif st_n == "FMRS" and ss_n == 24 and rdef.get("fmrs_tweak"):
                seed_val, delta_scale = rdef["fmrs_tweak"]
                vals = list(struct.unpack("<6f", sv_n))
                for vi in range(6):
                    s = ((seed_val * 31 + fmrs_idx * 17 + vi * 13) % 11) - 5
                    vals[vi] = max(-1.0, min(1.0, vals[vi] + s * 0.04 * delta_scale))
                fmrs_idx += 1
                out.extend(pack_sub("FMRS", struct.pack("<6f", *vals)))
            else:
                out.extend(raw_npc[sp_n : sp_n + 6 + ss_n])
            sp_n += 6 + ss_n
        comp_n = zlib.compress(bytes(out))
        return pack_record(
            "NPC_", rdef["npc_fid"], struct.pack("<I", len(out)) + comp_n, flags=0x00040000
        )

