    def make_friendly_animal_npc(
        new_fid: int,
        edid: str,
        full_name: str,
        shrt_name: str,
        src_npc_raw: bytes,
        is_companion_dog: bool = False,
    ) -> bytes:
        out = bytearray()
        out.extend(pack_zstr("EDID", edid))
        sp_a = 0
        wrote_snam = False
        wrote_pkid = False
        wrote_cnto = False
        wrote_full = False
        wrote_shrt = False
        wrote_doft = False
        in_obte = False
        dog_inv = [
            (0x001C32C8, 1),  # ClothesDog_ArmorMedium (Arneses de Perro de Presa Medios — ranura 0x00000800)
            (0x001C67B2, 1),  # ClothesDog_DogCollarReinforced (Collar de Perro Reforzado — ranura 0x00100000)
            (0x001B5ACC, 1),  # ClothesDog_ArmorLight (Arneses Ligeros opcionales en inventario)
            (0x001C67B4, 1),  # ClothesDog_DogHeadHelmet (Casco Canino opcional en inventario — ranura 0x00000100)
        ]
        companion_dog_perks = [
            0x00169693,
            0x001D4AB7,
            0x0004C935,
            0x000B9882,
            0x000B9883,
            0x000B9884,
            0x001D33D7,
            0x000A2775,
        ]
        while sp_a + 6 <= len(src_npc_raw):
            st_a = src_npc_raw[sp_a : sp_a + 4].decode("ascii", "ignore")
            ss_a = struct.unpack_from("<H", src_npc_raw, sp_a + 4)[0]
            sv_a = bytearray(src_npc_raw[sp_a + 6 : sp_a + 6 + ss_a])
            if st_a == "OBTE":
                in_obte = True
                out.extend(src_npc_raw[sp_a : sp_a + 6 + ss_a])
            elif st_a == "STOP":
                in_obte = False
                out.extend(src_npc_raw[sp_a : sp_a + 6 + ss_a])
            elif in_obte:
                if st_a == "FULL":
                    out.extend(pack_zstr("FULL", full_name))
                else:
                    out.extend(src_npc_raw[sp_a : sp_a + 6 + ss_a])
            elif st_a in ("EDID", "VMAD", "CRIF", "TPLT", "TPTA", "PKID"):
                pass
            elif st_a == "OBND" and is_companion_dog:
                out.extend(pack_sub("OBND", bytes.fromhex("f0ffc0ff000010002b004f00")))
            elif st_a == "RNAM" and is_companion_dog:
                out.extend(src_npc_raw[sp_a : sp_a + 6 + ss_a])
                out.extend(pack_sub("SPCT", struct.pack("<I", 1)))
                out.extend(pack_sub("SPLO", struct.pack("<I", 0x00215CD3)))
            elif st_a == "ECOR":
                out.extend(src_npc_raw[sp_a : sp_a + 6 + ss_a])
                if is_companion_dog:
                    out.extend(pack_sub("PRKZ", struct.pack("<I", len(companion_dog_perks))))
                    for p_fid in companion_dog_perks:
                        out.extend(pack_sub("PRKR", struct.pack("<IB", p_fid, 1)))
            elif st_a == "ACBS" and ss_a >= 4:
                fl_a = struct.unpack_from("<I", sv_a, 0)[0]
                if is_companion_dog:
                    fl_a |= 0x00000822  # Essential (0x02) + Unique (0x20) + Protected (0x800)
                    fl_a &= ~0x00000008
                else:
                    fl_a |= 0x00000020
                    fl_a &= ~0x0000080A
                struct.pack_into("<I", sv_a, 0, fl_a)
                if ss_a >= 16:
                    struct.pack_into("<H", sv_a, 14, 0)
                out.extend(pack_sub("ACBS", bytes(sv_a)))
            elif st_a == "SNAM":
                if not wrote_snam:
                    out.extend(pack_sub("SNAM", struct.pack("<IB", 0x0001C21C, 0)))
                    if is_companion_dog:
                        out.extend(pack_sub("SNAM", struct.pack("<IB", 0x00106C30, 0)))
                    wrote_snam = True
            elif st_a == "AIDT" and ss_a >= 4:
                if is_companion_dog and not wrote_cnto:
                    out.extend(pack_sub("COCT", struct.pack("<I", len(dog_inv))))
                    for d_item, d_cnt in dog_inv:
                        out.extend(pack_sub("CNTO", struct.pack("<II", d_item, d_cnt)))
                    wrote_cnto = True
                if is_companion_dog and ss_a >= 6:
                    sv_a[0] = 0    # Unaggressive until recruited (prevents auto-combat/auto-follow before recruitment)
                    sv_a[1] = 4    # Foolhardy (Confidence = 4.0 >= 2.5 -> holds position in Shady Sands until recruited)
                    sv_a[2] = 100  # Energy
                    sv_a[3] = 0    # Morality
                    sv_a[5] = 2    # Assistance = Helps Friends and Allies
                else:
                    sv_a[0] = 0    # Unaggressive
                    sv_a[3] = 0
                out.extend(pack_sub("AIDT", bytes(sv_a)))
                if not wrote_pkid:
                    if is_companion_dog:
                        out.extend(pack_sub("PKID", struct.pack("<I", 0x01001055)))  # V13DogmeatCloseFollowPack (ONLY active when Confidence < 2.5)
                        out.extend(pack_sub("PKID", struct.pack("<I", 0x01001050)))  # V13StayAtCurrentPositionPack (default hold position in Shady Sands)
                    else:
                        out.extend(pack_sub("PKID", struct.pack("<I", 0x01001050)))  # V13StayAtCurrentPositionPack
                        out.extend(pack_sub("PKID", struct.pack("<I", 0x00042A1C)))  # DefaultMasterPackage
                    wrote_pkid = True
            elif st_a == "DOFT" and is_companion_dog:
                if not wrote_doft:
                    out.extend(pack_sub("DOFT", struct.pack("<I", 0x0100102D)))
                    wrote_doft = True
            elif st_a == "CSCR" and is_companion_dog:
                out.extend(src_npc_raw[sp_a : sp_a + 6 + ss_a])
                if not wrote_doft:
                    out.extend(pack_sub("DOFT", struct.pack("<I", 0x0100102D)))
                    wrote_doft = True
            elif st_a == "FULL":
                out.extend(pack_zstr("FULL", full_name))
                wrote_full = True
            elif st_a == "SHRT":
                if not wrote_shrt:
                    out.extend(pack_zstr("SHRT", shrt_name))
                    wrote_shrt = True
            elif st_a == "DATA":
                if not wrote_full:
                    out.extend(pack_zstr("FULL", full_name))
                    wrote_full = True
                if not wrote_shrt:
                    out.extend(pack_zstr("SHRT", shrt_name))
                    wrote_shrt = True
                out.extend(src_npc_raw[sp_a : sp_a + 6 + ss_a])
            else:
                out.extend(src_npc_raw[sp_a : sp_a + 6 + ss_a])
            sp_a += 6 + ss_a
        if not wrote_full:
            out.extend(pack_zstr("FULL", full_name))
        if not wrote_shrt:
            out.extend(pack_zstr("SHRT", shrt_name))
        comp_a = zlib.compress(bytes(out))
        return pack_record("NPC_", new_fid, struct.pack("<I", len(out)) + comp_a, flags=0x00040000)

