        make_vendor_fact(0x01001C50, "V13VendorFactionKillianDarkwater", 0x010035E0)
        + make_vendor_fact(0x01001C51, "V13VendorFactionButchHarris", 0x010035E1)
        + make_vendor_fact(0x01001C52, "V13VendorFactionDrRazlo", 0x010035E2)
