    sp_pf = 0
    anam_idx = -1
    last_anam_pf = ""
    float_overrides = {
        5: 75.0,
        6: 135.0,
        7: 135.0,
        8: 180.0,
        9: 180.0,
        10: 320.0,
        20: 140.0,
        29: 75.0,
        30: 140.0,
    }
    while sp_pf + 6 <= len(raw_follow_pack):
        st_pf = raw_follow_pack[sp_pf : sp_pf + 4].decode("ascii", "ignore")
        ss_pf = struct.unpack_from("<H", raw_follow_pack, sp_pf + 4)[0]
        sv_pf = raw_follow_pack[sp_pf + 6 : sp_pf + 6 + ss_pf]
        if st_pf == "EDID":
            pass
        elif st_pf == "PSDT":
            pack_dog_follow_subs.extend(raw_follow_pack[sp_pf : sp_pf + 6 + ss_pf])
            # Only follow player when Confidence < 2.5 (set to 2.0 when DogmeatState == 1; 4.0 when unrecruited/dismissed/waiting)
            pack_dog_follow_subs.extend(
                pack_sub("CTDA", make_ctda_subject_getvalue(0x80, 0x000002BD, 2.5))
            )
        elif st_pf == "ANAM":
            anam_idx += 1
            last_anam_pf = sv_pf[:-1].decode("ascii", "ignore")
            pack_dog_follow_subs.extend(raw_follow_pack[sp_pf : sp_pf + 6 + ss_pf])
        elif st_pf == "CNAM" and last_anam_pf == "Float" and ss_pf == 4 and anam_idx in float_overrides:
            pack_dog_follow_subs.extend(pack_sub("CNAM", struct.pack("<f", float_overrides[anam_idx])))
        elif st_pf == "PLDT" and ss_pf == 16 and anam_idx in (0, 21, 24):
            pldt_b = bytearray(sv_pf)
            struct.pack_into("<I", pldt_b, 8, 160)
            pack_dog_follow_subs.extend(pack_sub("PLDT", bytes(pldt_b)))
        else:
            pack_dog_follow_subs.extend(raw_follow_pack[sp_pf : sp_pf + 6 + ss_pf])
        sp_pf += 6 + ss_pf

    grup_pack = pack_grup_top(
        b"PACK",
        pack_record("PACK", 0x01001050, bytes(pack_subs), fver=pk_fver, v2=pk_v2)
        + pack_record("PACK", 0x01001051, pack_wounded_sit_subs, fver=pk_fver, v2=pk_v2)
        + pack_record("PACK", 0x01001052, pack_jacoren_travel_subs, fver=pk_fver, v2=pk_v2)
        + pack_record("PACK", 0x01001053, pack_harry_evacuate_subs, fver=pk_fver, v2=pk_v2)
        + pack_record("PACK", 0x01001054, bytes(pack_harry_precombat_subs), fver=pk_fver, v2=pk_v2)
        + pack_record("PACK", 0x01001055, bytes(pack_dog_follow_subs), fver=pk_f_fver, v2=pk_f_v2),
    )

    # 12. MESG: 0x01001150..0x01001154 + Interactive Menus 0x01001156..0x0100115A
    def make_mesg_box(
        new_fid: int,
        edid: str,
        full_title: str,
        desc_txt: str,
        buttons: list[str],
    ) -> bytes:
        m_subs = bytearray()
        m_subs.extend(pack_zstr("EDID", edid))
        m_subs.extend(pack_zstr("DESC", desc_txt))
        m_subs.extend(pack_zstr("FULL", full_title))
        m_subs.extend(pack_sub("INAM", struct.pack("<I", 0)))
        m_subs.extend(pack_sub("DNAM", struct.pack("<I", 1)))
        for b_txt in buttons:
            m_subs.extend(pack_zstr("ITXT", b_txt))
        return pack_record("MESG", new_fid, bytes(m_subs))

