    def build_radio_qust_and_scene(playlist_fids: list[int]) -> bytes:
        rq_fid = 0x01008510
        rs_fid = 0x01008511
        rq_subs = bytearray()
        rq_subs.extend(pack_zstr("EDID", "V13RadioHubQuest"))
        rq_subs.extend(pack_sub("VMAD", build_simple_vmad("V13RadioQuestScript")))
        rq_subs.extend(pack_zstr("FULL", "Radio El Eje — Nueva California (2161)"))
        # DNAM: 0x0011 (Start Game Enabled + Allow Repeated Stages, NO Run Once), Priority 30
        rq_subs.extend(pack_sub("DNAM", bytes.fromhex("11001e000000000000000000")))
        rq_subs.extend(pack_sub("INDX", struct.pack("<HBB", 10, 2, 0)))
        rq_subs.extend(pack_sub("QSDT", b"\x00"))
        rq_subs.extend(pack_sub("NEXT", b""))  # Required stage/alias separator before ANAM
        rq_subs.extend(pack_sub("ANAM", struct.pack("<I", 1)))
        rq_subs.extend(pack_sub("ALST", struct.pack("<I", 0)))
        rq_subs.extend(pack_zstr("ALID", "TransmitterRef"))
        # FNAM: 0x0000400E (Optional 0x02 | Quest Object 0x04 | Allow Reserved 0x08 | Allow Disabled 0x4000)
        rq_subs.extend(pack_sub("FNAM", struct.pack("<I", 0x0000400E)))
        rq_subs.extend(pack_sub("ALFR", struct.pack("<I", 0x0100321F)))  # V13RadioHubTransmitterRef in CELL 0x00018AA2
        rq_subs.extend(pack_sub("ALDN", struct.pack("<I", 0x0100115E)))  # RadioDisplayV13Hub MESG
        rq_subs.extend(pack_sub("VTCK", struct.pack("<I", 0)))
        rq_subs.extend(pack_sub("ALED", b""))
        rq_rec = pack_record("QUST", rq_fid, bytes(rq_subs), fver=131, v2=7)

        rs_subs = bytearray()
        rs_subs.extend(pack_zstr("EDID", "V13RadioHubBroadcastScene"))
        # FNAM identical to RadioEyebotScene01 (0x000E0B60): 0x00000105 (Begin on Quest Start + Stop on Quest End + Radio Scene 0x0100)
        rs_subs.extend(pack_sub("FNAM", bytes.fromhex("05010000")))
        # Phase 0 ("V13RadioStartPhase" timer phase) + N phases for playlist tracks + 1 final loop phase
        total_phases = len(playlist_fids) + 2
        for _ph_i in range(total_phases):
            rs_subs.extend(pack_sub("HNAM", b""))
            rs_subs.extend(pack_zstr("NAM0", "V13RadioStartPhase" if _ph_i == 0 else ""))
            rs_subs.extend(pack_sub("NEXT", b""))
            rs_subs.extend(pack_sub("NEXT", b""))
            rs_subs.extend(pack_sub("WNAM", struct.pack("<I", 350)))
            rs_subs.extend(pack_sub("HNAM", b""))
        # Actor header for Alias 0 (TransmitterRef), matching GSRJ03_RadioMessage / RadioEyebotScene01
        rs_subs.extend(pack_sub("ALID", struct.pack("<I", 0)))
        rs_subs.extend(pack_sub("LNAM", struct.pack("<I", 0)))
        rs_subs.extend(pack_sub("DNAM", struct.pack("<I", 0x1A)))
        # Action 1 on Phase 0: Action Type 2 (Timer Action, 1.0s) matching RadioEyebotScene01
        rs_subs.extend(pack_sub("ANAM", struct.pack("<H", 2)))
        rs_subs.extend(pack_zstr("NAM0", ""))
        rs_subs.extend(pack_sub("ALID", struct.pack("<I", 0)))
        rs_subs.extend(pack_sub("INAM", struct.pack("<I", 1)))
        rs_subs.extend(pack_sub("SNAM", struct.pack("<I", 0)))
        rs_subs.extend(pack_sub("ENAM", struct.pack("<I", 0)))
        rs_subs.extend(pack_sub("SNAM", struct.pack("<f", 1.0)))
        rs_subs.extend(pack_sub("ANAM", b""))
        # Actions 2..N+1 on Phases 1..N: Action Type 6 (Radio Action) playing each SNDR via HTID
        for ph_i, sndr_fid in enumerate(playlist_fids, start=1):
            rs_subs.extend(pack_sub("ANAM", struct.pack("<H", 6)))  # Action Type 6 = Radio Scene Action
            rs_subs.extend(pack_zstr("NAM0", ""))
            rs_subs.extend(pack_sub("ALID", struct.pack("<I", 0)))
            rs_subs.extend(pack_sub("INAM", struct.pack("<I", ph_i + 1)))
            rs_subs.extend(pack_sub("SNAM", struct.pack("<I", ph_i)))
            rs_subs.extend(pack_sub("ENAM", struct.pack("<I", ph_i)))
            rs_subs.extend(pack_sub("DATA", struct.pack("<I", 0)))
            rs_subs.extend(pack_sub("HTID", struct.pack("<I", sndr_fid)))
            rs_subs.extend(pack_sub("DMAX", struct.pack("<I", 0)))
            rs_subs.extend(pack_sub("ANAM", b""))
        # Action N+2 on final phase (N+1): Action Type 4 (Start Scene Action) looping back to V13RadioStartPhase
        last_act_idx = len(playlist_fids) + 2
        last_ph_idx = len(playlist_fids) + 1
        rs_subs.extend(pack_sub("ANAM", struct.pack("<H", 4)))  # Action Type 4 = Start Scene Action (Loop)
        rs_subs.extend(pack_zstr("NAM0", ""))
        rs_subs.extend(pack_sub("ALID", struct.pack("<I", 0)))
        rs_subs.extend(pack_sub("INAM", struct.pack("<I", last_act_idx)))
        rs_subs.extend(pack_sub("SNAM", struct.pack("<I", last_ph_idx)))
        rs_subs.extend(pack_sub("ENAM", struct.pack("<I", last_ph_idx)))
        rs_subs.extend(pack_sub("LCEP", struct.pack("<I", rs_fid)))
        rs_subs.extend(pack_sub("INTT", struct.pack("<H", 0)))
        rs_subs.extend(pack_zstr("SSPN", "V13RadioStartPhase"))
        rs_subs.extend(pack_sub("CITC", struct.pack("<I", 0)))
        rs_subs.extend(pack_sub("ANAM", b""))

        rs_subs.extend(pack_sub("PNAM", struct.pack("<I", rq_fid)))
        rs_subs.extend(pack_sub("INAM", struct.pack("<I", last_act_idx)))
        rs_subs.extend(pack_sub("VNAM", struct.pack("<4I", 3, 3, 3, 3)))
        rs_subs.extend(pack_sub("XNAM", struct.pack("<I", 0)))
        rs_rec = pack_record("SCEN", rs_fid, bytes(rs_subs), fver=131, v2=10)

        rq_children_grup = (
            b"GRUP"
            + struct.pack("<IIIII", 24 + len(rs_rec), rq_fid, 10, 0, 0)
            + rs_rec
        )
        return rq_rec + rq_children_grup

    radio_qust_block = build_radio_qust_and_scene(radio_playlist_fids)

