    def build_tardis_qust_record() -> bytes:
        tq_fid = 0x01015000
        tq_subs = bytearray()
        tq_subs.extend(pack_zstr("EDID", "V13SideQuestTardis"))
        tq_subs.extend(pack_sub("VMAD", build_simple_vmad("V13SideQuestTardisScript")))
        tq_subs.extend(pack_zstr("FULL", "Encuentro Especial: La Cabina Telefónica Inusual"))
        dnam_b = bytearray.fromhex("11014e000000000007000000")
        tq_subs.extend(pack_sub("DNAM", bytes(dnam_b)))
        tq_subs.extend(pack_sub("XNAM", bytes.fromhex("588d1700")))
        tq_subs.extend(pack_sub("NEXT", b""))

        tq_subs.extend(pack_sub("INDX", struct.pack("<HBB", 10, 2, 0)))
        tq_subs.extend(pack_sub("QSDT", b"\x00"))
        for stg_id, qsdt_fl, cnam_txt in [
            (
                20,
                0,
                "En mitad del Desierto Central de Nueva California (entre Junktown y El Eje) se alza una antigua cabina telefónica policial británica azul de los años 60 («POLICE • PUBLIC CALL BOX»), idéntica al mítico Encuentro Especial del Fallout original (1997): «Ves una antigua cabina telefónica de policía. Parece estar totalmente fuera de lugar». Debo acercarme a examinar su puerta.",
            ),
            (
                25,
                0,
                "Al acercarme a la cabina telefónica policial azul, la lámpara blanca del techo comenzó a destellar con fuerza y escuché el inconfundible chirrido y gemido de sus frenos dimensionales antes de que la cabina entera se desmaterializara en el vórtice espacio-temporal. Justo donde se alzaba la cabina ha quedado sobre la arena un Sensor de Movimiento de RobCo. Debo recogerlo.",
            ),
            (
                30,
                1,
                "He recuperado el Sensor de Movimiento de RobCo dejado atrás por la Cabina Telefónica Inusual tras desmaterializarse en el Desierto Central de Nueva California. Mientras lo lleve conmigo, mi Pip-Boy ejecutará barridos periódicos de detección resaltando a los enemigos hostiles cercanos.",
            ),
        ]:
            tq_subs.extend(pack_sub("INDX", struct.pack("<HBB", stg_id, 0, 0)))
            tq_subs.extend(pack_sub("QSDT", struct.pack("<B", qsdt_fl)))
            tq_subs.extend(pack_zstr("CNAM", cnam_txt))

        for obj_id, obj_txt, obj_alias in [
            (20, "Acércate y examina la Cabina Telefónica Inusual (Police Call Box) en el Desierto Central", 0),
            (25, "Recoge el Sensor de Movimiento de RobCo dejado atrás por la cabina al desmaterializarse", 1),
        ]:
            tq_subs.extend(pack_sub("QOBJ", struct.pack("<H", obj_id)))
            tq_subs.extend(pack_sub("FNAM", struct.pack("<I", 0)))
            tq_subs.extend(pack_zstr("NNAM", obj_txt))
            tq_subs.extend(pack_sub("QSTA", struct.pack("<III", 2, 0, 0)))
            tq_subs.extend(pack_sub("CTDA", make_ctda_player_inworldspace(0x0000003C, 1.0)))
            tq_subs.extend(pack_sub("QSTA", struct.pack("<III", 3, 0, 0)))
            tq_subs.extend(pack_sub("CTDA", make_ctda_player_incell(0x01002000, 1.0)))
            tq_subs.extend(pack_sub("QSTA", struct.pack("<III", 5, 0, 0)))
            tq_subs.extend(pack_sub("CTDA", make_ctda_player_incell(0x01002100, 1.0)))
            tq_subs.extend(pack_sub("QSTA", struct.pack("<III", obj_alias, 0, 0)))
            tq_subs.extend(pack_sub("CTDA", make_ctda_player_inworldspace(0x01003400, 1.0)))
            tq_subs.extend(pack_sub("QSTA", struct.pack("<III", 7, 0, 0)))
            tq_subs.extend(pack_sub("CTDA", make_ctda_player_incell(0x01002200, 1.0)))

        tardis_aliases = [
            (0, "Alias_TardisCallBox", 0x010035F0),
            (1, "Alias_TardisMotionSensor", 0x010035F2),
            (2, "Alias_MnemosyneExtDoor_V13SideQuestTardis", 0x01003005),
            (3, "Alias_MnemosyneV13Door_V13SideQuestTardis", 0x01002003),
            (4, "Alias_CaveRouteMap_V13SideQuestTardis", 0x01003528),
            (5, "Alias_V13ExpeditionDoor_V13SideQuestTardis", 0x01002101),
            (6, "Alias_CaveElevatorToV13_V13SideQuestTardis", 0x01003501),
            (7, "Alias_DungeonExitDoor_V13SideQuestTardis", 0x01002206),
            (8, "Alias_MnemosyneTerminal_V13SideQuestTardis", 0x01002035),
            (9, "Alias_TardisAnomalyDeskTerm", 0x010035F4),
        ]
        tq_subs.extend(pack_sub("ANAM", struct.pack("<I", 10)))
        for al_idx, al_name, al_refr in tardis_aliases:
            tq_subs.extend(pack_sub("ALST", struct.pack("<I", al_idx)))
            tq_subs.extend(pack_zstr("ALID", al_name))
            tq_subs.extend(pack_sub("FNAM", struct.pack("<I", 0x0000529A)))
            tq_subs.extend(pack_sub("ALFR", struct.pack("<I", al_refr)))
            tq_subs.extend(pack_sub("VTCK", struct.pack("<I", 0)))
            tq_subs.extend(pack_sub("ALED", b""))
        return pack_record("QUST", tq_fid, bytes(tq_subs))

    tardis_qust_block = build_tardis_qust_record()

