                # Solid level cave floor slab under Set's checkpoint gate/terminal/chest in the South-East Basin (1486, -3650, -1028)
                necro_cavern_temp_props.append((0x01009006, (1486.0, -3650.0, -1028.0, 0.0, 0.0, 0.0), None))

                _cand_tris: list[tuple[float, float, float, float]] = []
