                    _ux, _uy, _uz = _x1 - _x0, _y1 - _y0, _z1 - _z0
                    _vx, _vy, _vz = _x2 - _x0, _y2 - _y0, _z2 - _z0
                    _nx = _uy * _vz - _uz * _vy
                    _ny = _uz * _vx - _ux * _vz
                    _nz = _ux * _vy - _uy * _vx
                    _nlen = (_nx * _nx + _ny * _ny + _nz * _nz) ** 0.5
