    def _is_clear_of_bunkers(wx_pt: float, wy_pt: float) -> bool:
        if wx_pt < _coastline_x(wy_pt) + 350.0:
            return False
        for bx_c, by_c, br_c in bunker_clear_zones:
            if math.hypot(wx_pt - bx_c, wy_pt - by_c) < br_c:
                return False
        return True

